window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[58]={"5800":{"example:5800:exzh":"That tragedy is impossible to forget.","example:5800:exzh2":"When a tragedy happens, people grieve.","example:5800:exzh3":"Measures are needed to prevent tragedies.","example:5800:exzh4":"After the tragedy, the community came together.","example:5800:exzh5":"Let's learn lessons from tragedies in history."},"5801":{"example:5801:exzh":"I bought a new calendar.","example:5801:exzh2":"Please write important days on the calendar.","example:5801:exzh3":"I'll check the calendar to confirm my plans.","example:5801:exzh4":"Calendars change every year.","example:5801:exzh5":"I use a calendar to manage my time.","grammar:5801:ex:trans":"I bought a new calendar.","grammar:5801:ex:structure":"i-adjective＋nounを＋買いました.","grammar:5801:ex:explain":"This is the basic pattern 「i-adjective＋nounを＋transitive verb」. 「新しい」 is an i-adjective and goes directly before the noun 「カレンダー」 (calendar) to modify it (i-adjectives modify nouns without a particle), giving 「新しいカレンダー」 = a new calendar. 「を」 marks it as the object of 「買う」 (to buy). The past form 「買いました」 is polite. The whole sentence 「新しいカレンダーを買いました」 means I bought a new calendar.","grammar:5801:ex:words:0:zh":"new","grammar:5801:ex:words:0:note":"あたらしい","grammar:5801:ex:words:0:pos":"adjective","grammar:5801:ex:words:1:zh":"calendar","grammar:5801:ex:words:1:note":"Loanword calendar","grammar:5801:ex:words:1:pos":"noun","grammar:5801:ex:words:2:zh":"(object marker)","grammar:5801:ex:words:2:pos":"particle","grammar:5801:ex:words:3:zh":"bought","grammar:5801:ex:words:3:note":"かいました","grammar:5801:ex:words:3:pos":"verb","grammar:5801:ex:points:0":"カレンダー: calendar","grammar:5801:ex:points:1":"新しいカレンダー: a new calendar","grammar:5801:ex2:trans":"Please write the important dates on the calendar.","grammar:5801:ex2:structure":"nounに＋〔重要な日〕＋を＋書き込んでください. 「〜に書き込む」 = to write in …","grammar:5801:ex2:words:0:zh":"calendar","grammar:5801:ex2:words:0:note":"loanword","grammar:5801:ex2:words:0:pos":"noun","grammar:5801:ex2:words:1:zh":"(the destination)","grammar:5801:ex2:words:1:pos":"particle","grammar:5801:ex2:words:2:zh":"important","grammar:5801:ex2:words:2:note":"じゅうよう","grammar:5801:ex2:words:2:pos":"na-adjective","grammar:5801:ex2:words:3:zh":"day","grammar:5801:ex2:words:3:note":"ひ","grammar:5801:ex2:words:3:pos":"noun","grammar:5801:ex2:words:4:zh":"(object marker)","grammar:5801:ex2:words:4:pos":"particle","grammar:5801:ex2:words:5:zh":"to write in","grammar:5801:ex2:words:5:note":"かきこんで; te-form","grammar:5801:ex2:words:5:pos":"verb","grammar:5801:ex2:words:6:zh":"please","grammar:5801:ex2:words:6:note":"〜てください","grammar:5801:ex2:words:6:pos":"verb","grammar:5801:ex2:points:0":"書き込む: to write in, to fill in","grammar:5801:ex2:points:1":"重要な日: an important date","grammar:5801:ex3:trans":"I look at the calendar and check the schedule.","grammar:5801:ex3:structure":"nounを＋〔見て〕, 予定を＋確認します. 「見て」 links with the te-form.","grammar:5801:ex3:words:0:zh":"calendar","grammar:5801:ex3:words:0:note":"loanword","grammar:5801:ex3:words:0:pos":"noun","grammar:5801:ex3:words:1:zh":"(object marker)","grammar:5801:ex3:words:1:pos":"particle","grammar:5801:ex3:words:2:zh":"look (and)","grammar:5801:ex3:words:2:note":"みて; te-form","grammar:5801:ex3:words:2:pos":"verb","grammar:5801:ex3:words:3:zh":"arrangements","grammar:5801:ex3:words:3:note":"よてい","grammar:5801:ex3:words:3:pos":"noun","grammar:5801:ex3:words:4:zh":"(object marker)","grammar:5801:ex3:words:4:pos":"particle","grammar:5801:ex3:words:5:zh":"confirm","grammar:5801:ex3:words:5:note":"かくにんします","grammar:5801:ex3:words:5:pos":"verb","grammar:5801:ex3:points:0":"te-form link: 見て確認する (look and check)","grammar:5801:ex3:points:1":"予定を確認する: to check the schedule","grammar:5801:ex4:trans":"The calendar changes every year.","grammar:5801:ex4:structure":"nounは＋毎年＋変わります. 「変わる」 is an intransitive verb.","grammar:5801:ex4:words:0:zh":"calendar","grammar:5801:ex4:words:0:note":"loanword","grammar:5801:ex4:words:0:pos":"noun","grammar:5801:ex4:words:1:zh":"(topic marker)","grammar:5801:ex4:words:1:pos":"particle","grammar:5801:ex4:words:2:zh":"every year","grammar:5801:ex4:words:2:note":"まいとし","grammar:5801:ex4:words:2:pos":"noun","grammar:5801:ex4:words:3:zh":"change","grammar:5801:ex4:words:3:note":"かわります","grammar:5801:ex4:words:3:pos":"verb","grammar:5801:ex4:points:0":"変わる: (intransitive verb) to change","grammar:5801:ex4:points:1":"毎年: every year","grammar:5801:ex5:trans":"I use a calendar to manage time.","grammar:5801:ex5:structure":"nounを＋〔使って〕, 時間を＋管理しています. 「〜を使って」 = using … (a means).","grammar:5801:ex5:words:0:zh":"calendar","grammar:5801:ex5:words:0:note":"loanword","grammar:5801:ex5:words:0:pos":"noun","grammar:5801:ex5:words:1:zh":"(object marker)","grammar:5801:ex5:words:1:pos":"particle","grammar:5801:ex5:words:2:zh":"using (and then)","grammar:5801:ex5:words:2:note":"Te-form expressing means","grammar:5801:ex5:words:2:pos":"verb","grammar:5801:ex5:words:3:zh":"time","grammar:5801:ex5:words:3:note":"じかん","grammar:5801:ex5:words:3:pos":"noun","grammar:5801:ex5:words:4:zh":"(object marker)","grammar:5801:ex5:words:4:pos":"particle","grammar:5801:ex5:words:5:zh":"management","grammar:5801:ex5:words:5:note":"〜ている expresses a state","grammar:5801:ex5:words:5:pos":"verb","grammar:5801:ex5:points:0":"〜を使って: using … (te-form for means)","grammar:5801:ex5:points:1":"管理する: to manage"},"5802":{"example:5802:exzh":"I put a wallet in my pocket.","example:5802:exzh2":"I heard a sound coming from my pocket.","example:5802:exzh3":"I put my hands in my pocket and warmed them.","example:5802:exzh4":"I took the key out of my pocket.","example:5802:exzh5":"I need to tidy up the things in my pocket."},"5803":{"example:5803:exzh":"Our culture has historical ties.","example:5803:exzh2":"I'm together with friends with whom I have strong ties.","example:5803:exzh3":"This research explores connections between different fields.","example:5803:exzh4":"Our country needs international ties.","example:5803:exzh5":"Family ties are extremely important."},"5804":{"example:5804:exzh":"This term has a specialized meaning.","example:5804:exzh2":"Please be careful about how you use the term.","example:5804:exzh3":"He has a good understanding of the terms used in that field.","example:5804:exzh4":"New terms are being born one after another.","example:5804:exzh5":"This term differs across cultures."},"5805":{"example:5805:exzh":"Are there any vacancies in this apartment building?","example:5805:exzh2":"I found a vacancy near the station.","example:5805:exzh3":"Please let me know if there's a vacancy.","example:5805:exzh4":"There is no vacancy in this room.","example:5805:exzh5":"Please contact me right away if a vacancy opens up."},"5806":{"example:5806:exzh":"Swimming is my favorite sport.","example:5806:exzh2":"I swim every day.","example:5806:exzh3":"I took part in a swimming competition.","example:5806:exzh4":"The children are learning to swim.","example:5806:exzh5":"I like enjoying swimming in summer.","grammar:5806:ex:trans":"Swimming is a sport I like.","grammar:5806:ex:structure":"nounは＋〔私の好きなスポーツ〕＋です. 「好きな」 modifies with な.","grammar:5806:ex:explain":"Note that 「好き」 is a na-adjective (adjectival noun); to modify the following noun 「スポーツ」 it must take 「な」, giving 「好きな」. 「私の」 uses 「の」 to show belonging, so the whole phrase 「私の好きなスポーツ」 forms a single noun phrase meaning a sport I like. The topic 「水泳」 is marked with 「は」, and the sentence-final 「です」 is the polite copula, forming the most basic 「AはBです」 identifying sentence.","grammar:5806:ex:words:0:zh":"to swim","grammar:5806:ex:words:0:note":"すいえい","grammar:5806:ex:words:0:pos":"noun","grammar:5806:ex:words:1:zh":"(topic marker)","grammar:5806:ex:words:1:pos":"particle","grammar:5806:ex:words:2:zh":"I","grammar:5806:ex:words:2:note":"わたし","grammar:5806:ex:words:2:pos":"pronoun","grammar:5806:ex:words:3:zh":"'s","grammar:5806:ex:words:3:pos":"particle","grammar:5806:ex:words:4:zh":"liked / favorite","grammar:5806:ex:words:4:note":"すき","grammar:5806:ex:words:4:pos":"na-adjective","grammar:5806:ex:words:5:zh":"exercise","grammar:5806:ex:words:5:note":"loanword","grammar:5806:ex:words:5:pos":"noun","grammar:5806:ex:words:6:zh":"is","grammar:5806:ex:words:6:pos":"copula","grammar:5806:ex:points:0":"好きな＋noun: the … one likes","grammar:5806:ex:points:1":"水泳: swimming","grammar:5806:ex2:trans":"I swim every day.","grammar:5806:ex2:structure":"time, nounを＋しています. 「水泳をする」 = to swim. 「毎日」 expresses a habit.","grammar:5806:ex2:words:0:zh":"every day","grammar:5806:ex2:words:0:note":"まいにち","grammar:5806:ex2:words:0:pos":"noun","grammar:5806:ex2:words:1:zh":"to swim","grammar:5806:ex2:words:1:note":"すいえい","grammar:5806:ex2:words:1:pos":"noun","grammar:5806:ex2:words:2:zh":"(object marker)","grammar:5806:ex2:words:2:pos":"particle","grammar:5806:ex2:words:3:zh":"do","grammar:5806:ex2:words:3:note":"〜ている marks habit","grammar:5806:ex2:words:3:pos":"verb","grammar:5806:ex2:points:0":"水泳をする: to swim","grammar:5806:ex2:points:1":"毎日: every day","grammar:5806:ex3:trans":"I took part in a swimming competition.","grammar:5806:ex3:structure":"〔水泳の大会〕＋に＋参加しました. 「〜に参加する」 = to take part in …","grammar:5806:ex3:words:0:zh":"to swim","grammar:5806:ex3:words:0:note":"すいえい","grammar:5806:ex3:words:0:pos":"noun","grammar:5806:ex3:words:1:zh":"'s","grammar:5806:ex3:words:1:pos":"particle","grammar:5806:ex3:words:2:zh":"competition","grammar:5806:ex3:words:2:note":"たいかい","grammar:5806:ex3:words:2:pos":"noun","grammar:5806:ex3:words:3:zh":"(object)","grammar:5806:ex3:words:3:pos":"particle","grammar:5806:ex3:words:4:zh":"attended","grammar:5806:ex3:words:4:note":"さんかしました","grammar:5806:ex3:words:4:pos":"verb","grammar:5806:ex3:points:0":"水泳の大会: swimming competition","grammar:5806:ex3:points:1":"〜に参加する: to take part in ...","grammar:5806:ex4:trans":"The children are learning to swim.","grammar:5806:ex4:structure":"〜は＋nounを＋学んでいます.","grammar:5806:ex4:words:0:zh":"children","grammar:5806:ex4:words:0:note":"こどもたち","grammar:5806:ex4:words:0:pos":"noun","grammar:5806:ex4:words:1:zh":"(topic marker)","grammar:5806:ex4:words:1:pos":"particle","grammar:5806:ex4:words:2:zh":"to swim","grammar:5806:ex4:words:2:note":"すいえい","grammar:5806:ex4:words:2:pos":"noun","grammar:5806:ex4:words:3:zh":"(object marker)","grammar:5806:ex4:words:3:pos":"particle","grammar:5806:ex4:words:4:zh":"study","grammar:5806:ex4:words:4:note":"〜ている marks an ongoing action","grammar:5806:ex4:words:4:pos":"verb","grammar:5806:ex4:points:0":"学ぶ: to learn","grammar:5806:ex4:points:1":"水泳: swimming","grammar:5806:ex5:trans":"I like swimming in the summer.","grammar:5806:ex5:structure":"〔夏に水泳を楽しむ＋の〕＋が＋好きです. 「夏に」 = in the summer.","grammar:5806:ex5:words:0:zh":"summer","grammar:5806:ex5:words:0:note":"なつ","grammar:5806:ex5:words:0:pos":"noun","grammar:5806:ex5:words:1:zh":"(point in time)","grammar:5806:ex5:words:1:pos":"particle","grammar:5806:ex5:words:2:zh":"to swim","grammar:5806:ex5:words:2:note":"すいえい","grammar:5806:ex5:words:2:pos":"noun","grammar:5806:ex5:words:3:zh":"(object marker)","grammar:5806:ex5:words:3:pos":"particle","grammar:5806:ex5:words:4:zh":"enjoy","grammar:5806:ex5:words:4:note":"たのしむ; dictionary form","grammar:5806:ex5:words:4:pos":"verb","grammar:5806:ex5:words:5:zh":"(nominalizer)","grammar:5806:ex5:words:5:pos":"particle","grammar:5806:ex5:words:6:zh":"(object marker)","grammar:5806:ex5:words:6:pos":"particle","grammar:5806:ex5:words:7:zh":"to like","grammar:5806:ex5:words:7:note":"すき","grammar:5806:ex5:words:7:pos":"na-adjective","grammar:5806:ex5:words:8:zh":"(polite form)","grammar:5806:ex5:words:8:pos":"copula","grammar:5806:ex5:points:0":"〜に: in / at … (夏に = in the summer)","grammar:5806:ex5:points:1":"verb + の + が好き: like doing…"},"5807":{"example:5807:exzh":"He always speaks with consideration for the other person's feelings.","example:5807:exzh2":"It's a society where consideration matters.","example:5807:exzh3":"I think consideration is necessary.","example:5807:exzh4":"Let's act without forgetting to be considerate.","example:5807:exzh5":"We should avoid behavior that lacks consideration."},"5809":{"example:5809:exzh":"Forming a team is important.","example:5809:exzh2":"I'm teaming up with him to move the project forward.","example:5809:exzh3":"I'll team up with a new member.","example:5809:exzh4":"We don't have time, so let's team up quickly.","example:5809:exzh5":"We can team up together."},"5810":{"example:5810:exzh":"This plate is high-end.","example:5810:exzh2":"I need a new plate for serving the food.","example:5810:exzh3":"We serve it on a large platter.","example:5810:exzh4":"I threw away the old plate.","example:5810:exzh5":"This plate is my favorite."},"5811":{"example:5811:exzh":"I trust his sincerity.","example:5811:exzh2":"I'll respond with sincerity.","example:5811:exzh3":"I think sincerity is important.","example:5811:exzh4":"I want to show sincerity in my gratitude.","example:5811:exzh5":"I'll treat people with sincerity."},"5812":{"example:5812:exzh":"The temperature is high today, isn't it?","example:5812:exzh2":"When the temperature drops, it gets cold.","example:5812:exzh3":"In summer, the temperature tends to rise.","example:5812:exzh4":"When the temperature falls below 10 degrees, it may snow.","example:5812:exzh5":"The temperature varies considerably from region to region.","grammar:5812:ex:trans":"The temperature is high today, isn't it?","grammar:5812:ex:structure":"今日は、気温が＋高いですね。「気温」＝air temperature; 「気温が高い」＝the temperature is high.","grammar:5812:ex:explain":"This sentence has a “major subject plus minor subject” structure: 「は」 first establishes 「今日」 as the broader topic, then 「が」 identifies 「気温」 as what is actually being described, forming 「今日は気温が高い」, meaning “As for today, the temperature is high.” 「高い」 is an い-adjective; adding 「です」 directly makes it polite. The sentence-final particle 「ね」 seeks agreement and creates a sense of connection, like “isn't it?” or “right?” in English.","grammar:5812:ex:words:0:zh":"today","grammar:5812:ex:words:0:note":"きょう","grammar:5812:ex:words:0:pos":"noun","grammar:5812:ex:words:1:zh":"(topic marker)","grammar:5812:ex:words:1:pos":"particle","grammar:5812:ex:words:2:zh":"temperature","grammar:5812:ex:words:2:note":"きおん","grammar:5812:ex:words:2:pos":"noun","grammar:5812:ex:words:3:zh":"(nominative)","grammar:5812:ex:words:3:pos":"particle","grammar:5812:ex:words:4:zh":"high","grammar:5812:ex:words:4:note":"たかい","grammar:5812:ex:words:4:pos":"adjective","grammar:5812:ex:words:5:zh":"(polite form)","grammar:5812:ex:words:5:pos":"copula","grammar:5812:ex:words:6:zh":"right?","grammar:5812:ex:words:6:note":"shared agreement","grammar:5812:ex:words:6:pos":"particle","grammar:5812:ex:points:0":"気温（きおん）：air temperature","grammar:5812:ex:points:1":"気温が高い：the temperature is high","grammar:5812:ex2:trans":"It gets cold when the temperature drops.","grammar:5812:ex2:structure":"〔気温が下がる＋と〕、寒くなります。「気温が下がる」＝the temperature drops; 「と」 expresses an inevitable result; 「寒くなる」＝get cold.","grammar:5812:ex2:words:0:zh":"temperature","grammar:5812:ex2:words:0:note":"きおん","grammar:5812:ex2:words:0:pos":"noun","grammar:5812:ex2:words:1:zh":"(nominative)","grammar:5812:ex2:words:1:pos":"particle","grammar:5812:ex2:words:2:zh":"go down","grammar:5812:ex2:words:2:note":"さがる; dictionary form","grammar:5812:ex2:words:2:pos":"verb","grammar:5812:ex2:words:3:zh":"(as soon as…)","grammar:5812:ex2:words:3:pos":"particle","grammar:5812:ex2:words:4:zh":"to get cold","grammar:5812:ex2:words:4:note":"〜くなる","grammar:5812:ex2:words:4:pos":"adjective","grammar:5812:ex2:points:0":"気温が下がる: the temperature drops","grammar:5812:ex2:points:1":"〜と: as soon as… / whenever… ; 寒くなる: get cold","grammar:5812:ex3:trans":"The temperature tends to rise easily in summer.","grammar:5812:ex3:structure":"夏は、気温が＋上がりやすいです. 「〜やすい」 = easy to …; 「上がりやすい」 = tends to rise easily.","grammar:5812:ex3:words:0:zh":"summer","grammar:5812:ex3:words:0:note":"なつ","grammar:5812:ex3:words:0:pos":"noun","grammar:5812:ex3:words:1:zh":"(topic marker)","grammar:5812:ex3:words:1:pos":"particle","grammar:5812:ex3:words:2:zh":"temperature","grammar:5812:ex3:words:2:note":"きおん","grammar:5812:ex3:words:2:pos":"noun","grammar:5812:ex3:words:3:zh":"(nominative)","grammar:5812:ex3:words:3:pos":"particle","grammar:5812:ex3:words:4:zh":"tends to rise easily","grammar:5812:ex3:words:4:note":"〜やすい","grammar:5812:ex3:words:4:pos":"adjective","grammar:5812:ex3:words:5:zh":"(polite form)","grammar:5812:ex3:words:5:pos":"copula","grammar:5812:ex3:points:0":"気温が上がる: the temperature rises","grammar:5812:ex3:points:1":"〜やすい: easy to … (上がりやすい = tends to rise easily)","grammar:5812:ex4:trans":"When the temperature falls below 10 degrees, it may snow.","grammar:5812:ex4:structure":"〔気温が10度を下回る＋と〕、〔雪が降る＋ことがあります〕. 「〜を下回る」 = fall below …; 「〜ことがある」 = sometimes ….","grammar:5812:ex4:words:0:zh":"temperature","grammar:5812:ex4:words:0:note":"きおん","grammar:5812:ex4:words:0:pos":"noun","grammar:5812:ex4:words:1:zh":"(nominative)","grammar:5812:ex4:words:1:pos":"particle","grammar:5812:ex4:words:2:zh":"10 degrees","grammar:5812:ex4:words:2:note":"じゅうど","grammar:5812:ex4:words:2:pos":"noun","grammar:5812:ex4:words:3:zh":"(object marker)","grammar:5812:ex4:words:3:pos":"particle","grammar:5812:ex4:words:4:zh":"fall below","grammar:5812:ex4:words:4:note":"したまわる; dictionary form","grammar:5812:ex4:words:4:pos":"verb","grammar:5812:ex4:words:5:zh":"(as soon as…)","grammar:5812:ex4:words:5:pos":"particle","grammar:5812:ex4:words:6:zh":"snow","grammar:5812:ex4:words:6:note":"ゆき","grammar:5812:ex4:words:6:pos":"noun","grammar:5812:ex4:words:7:zh":"(nominative)","grammar:5812:ex4:words:7:pos":"particle","grammar:5812:ex4:words:8:zh":"down","grammar:5812:ex4:words:8:note":"dictionary form modification","grammar:5812:ex4:words:8:pos":"verb","grammar:5812:ex4:words:9:zh":"(nominalizer)","grammar:5812:ex4:words:9:pos":"noun","grammar:5812:ex4:words:10:zh":"(nominative)","grammar:5812:ex4:words:10:pos":"particle","grammar:5812:ex4:words:11:zh":"there is / are","grammar:5812:ex4:words:11:note":"〜ことがある","grammar:5812:ex4:words:11:pos":"verb","grammar:5812:ex4:points:0":"気温が10度を下回る: the temperature falls below 10 degrees","grammar:5812:ex4:points:1":"〜ことがある: sometimes … (雪が降ることがある = it may snow)","grammar:5812:ex5:trans":"Temperatures vary greatly from region to region.","grammar:5812:ex5:structure":"〔地方によって〕、気温が＋かなり＋違います. 「〜によって」 = depending on …; varies according to …; 「かなり違う」 = differ considerably.","grammar:5812:ex5:words:0:zh":"area","grammar:5812:ex5:words:0:note":"ちほう","grammar:5812:ex5:words:0:pos":"noun","grammar:5812:ex5:words:1:zh":"basis, grounds","grammar:5812:ex5:words:1:note":"〜によって","grammar:5812:ex5:words:1:pos":"Expression","grammar:5812:ex5:words:2:zh":"temperature","grammar:5812:ex5:words:2:note":"きおん","grammar:5812:ex5:words:2:pos":"noun","grammar:5812:ex5:words:3:zh":"(nominative)","grammar:5812:ex5:words:3:pos":"particle","grammar:5812:ex5:words:4:zh":"quite","grammar:5812:ex5:words:4:pos":"adverb","grammar:5812:ex5:words:5:zh":"differ","grammar:5812:ex5:words:5:note":"ちがいます","grammar:5812:ex5:words:5:pos":"verb","grammar:5812:ex5:points:0":"〜によって: varies according to … (地方によって = varies by region)","grammar:5812:ex5:points:1":"かなり違う: differ considerably"},"5813":{"example:5813:exzh":"He is the president of the country.","example:5813:exzh2":"The president makes important decisions.","example:5813:exzh3":"A new president has been elected.","example:5813:exzh4":"The president's speech influences many people.","example:5813:exzh5":"The president's official residence is beautiful."},"5815":{"example:5815:exzh":"He is a very humble person.","example:5815:exzh2":"Humility is one of the virtues.","example:5815:exzh3":"She has a humble attitude.","example:5815:exzh4":"Being humble has a positive effect on personal relationships.","example:5815:exzh5":"Humble, yet full of confidence."},"5816":{"example:5816:exzh":"He is holed up at home.","example:5816:exzh2":"Lately I've been avoiding meeting friends and staying shut up at home.","example:5816:exzh3":"She often shuts herself up in her room.","example:5816:exzh4":"Sometimes it's necessary to shut yourself in.","example:5816:exzh5":"He felt stressed and had shut himself away."},"5817":{"example:5817:exzh":"He managed to see the situation clearly.","example:5817:exzh2":"It's difficult to discern a good choice.","example:5817:exzh3":"It's important to see your own feelings clearly.","example:5817:exzh4":"She is trying to gauge the other person's intentions.","example:5817:exzh5":"Seeing things clearly requires a lot of experience."},"5818":{"example:5818:exzh":"He is the director of the hospital.","example:5818:exzh2":"I'll act according to the director's instructions.","example:5818:exzh3":"A new director has taken office.","example:5818:exzh4":"I had a chance to meet with the director.","example:5818:exzh5":"I respect the director's ideas."},"5819":{"example:5819:exzh":"I've been to Beijing.","example:5819:exzh2":"Beijing is the capital of China.","example:5819:exzh3":"Spring in Beijing is very beautiful.","example:5819:exzh4":"He speaks the Beijing dialect.","example:5819:exzh5":"A famous dish in Beijing is Peking duck."},"5820":{"example:5820:exzh":"I felt relieved when the exam was over.","example:5820:exzh2":"I felt relieved when I got her call.","example:5820:exzh3":"I like those moments of relief.","example:5820:exzh4":"I felt relieved and smiled.","example:5820:exzh5":"I'm listening to relaxing music."},"5821":{"example:5821:exzh":"I met a friend the other day.","example:5821:exzh2":"The other day I went to see a movie.","example:5821:exzh3":"Do you remember what we talked about the other day?","example:5821:exzh4":"Last weekend was fun.","example:5821:exzh5":"The trip the other day was fun.","grammar:5821:ex:trans":"I met a friend the other day.","grammar:5821:ex:structure":"こないだ〜に会いました","grammar:5821:ex:explain":"The person you meet with 「会う」 (to meet) takes 「に」, so 「友達に会う」 means to meet a friend; this 「に」 cannot be replaced with 「を」, a point learners often get wrong. At the start of the sentence, 「こないだ」 is the casual contraction of 「この間」, meaning the other day or last time. The final 「会いました」 is the polite past form, stating a meeting that already happened.","grammar:5821:ex:words:0:zh":"the other day","grammar:5821:ex:words:0:note":"こないだ","grammar:5821:ex:words:0:pos":"adverb","grammar:5821:ex:words:1:zh":"friend","grammar:5821:ex:words:1:note":"ともだち","grammar:5821:ex:words:1:pos":"noun","grammar:5821:ex:words:2:zh":"(object)","grammar:5821:ex:words:2:pos":"particle","grammar:5821:ex:words:3:zh":"met","grammar:5821:ex:words:3:note":"あいました","grammar:5821:ex:words:3:pos":"verb","grammar:5821:ex:points:0":"❗この間 (このあいだ): the other day, last time; in casual speech it is often shortened to 「こないだ」; 〜に会う = to meet …","grammar:5821:ex:points:1":"この間: the other day.","grammar:5821:ex2:trans":"The other day I went to see a movie.","grammar:5821:ex2:structure":"こないだ〜を見に行った","grammar:5821:ex2:words:0:zh":"the other day","grammar:5821:ex2:words:0:note":"こないだ","grammar:5821:ex2:words:0:pos":"adverb","grammar:5821:ex2:words:1:zh":"movie","grammar:5821:ex2:words:1:note":"えいが","grammar:5821:ex2:words:1:pos":"noun","grammar:5821:ex2:words:2:zh":"(object marker)","grammar:5821:ex2:words:2:pos":"particle","grammar:5821:ex2:words:3:zh":"went to see","grammar:5821:ex2:words:3:note":"みにいった","grammar:5821:ex2:words:3:pos":"verb","grammar:5821:ex2:points:0":"❗こないだ = この間 (casual speech); 映画を見に行く = to go see a movie.","grammar:5821:ex2:points:1":"こないだ: the other day.","grammar:5821:ex3:trans":"Do you remember what we talked about the other day?","grammar:5821:ex3:structure":"こないだの〜を覚えていますか","grammar:5821:ex3:words:0:zh":"the other day","grammar:5821:ex3:words:0:note":"こないだ","grammar:5821:ex3:words:0:pos":"adverb","grammar:5821:ex3:words:1:zh":"'s","grammar:5821:ex3:words:1:pos":"particle","grammar:5821:ex3:words:2:zh":"thing / matter","grammar:5821:ex3:words:2:note":"はなし","grammar:5821:ex3:words:2:pos":"noun","grammar:5821:ex3:words:3:zh":"(object marker)","grammar:5821:ex3:words:3:pos":"particle","grammar:5821:ex3:words:4:zh":"remember","grammar:5821:ex3:words:4:note":"おぼえています","grammar:5821:ex3:words:4:pos":"verb","grammar:5821:ex3:words:5:zh":"(question)","grammar:5821:ex3:words:5:pos":"particle","grammar:5821:ex3:points:0":"❗こないだの話: the talk from last time (こないだ + の + noun).","grammar:5821:ex3:points:1":"こないだの話: the talk from the other day.","grammar:5821:ex4:trans":"Last weekend was fun.","grammar:5821:ex4:structure":"こないだの〜は楽しかったです","grammar:5821:ex4:words:0:zh":"the other day","grammar:5821:ex4:words:0:note":"こないだ","grammar:5821:ex4:words:0:pos":"adverb","grammar:5821:ex4:words:1:zh":"'s","grammar:5821:ex4:words:1:pos":"particle","grammar:5821:ex4:words:2:zh":"weekend","grammar:5821:ex4:words:2:note":"しゅうまつ","grammar:5821:ex4:words:2:pos":"noun","grammar:5821:ex4:words:3:zh":"(topic)","grammar:5821:ex4:words:3:pos":"particle","grammar:5821:ex4:words:4:zh":"(past) had fun","grammar:5821:ex4:words:4:note":"たのしかった","grammar:5821:ex4:words:4:pos":"adjective","grammar:5821:ex4:words:5:zh":"(polite form)","grammar:5821:ex4:words:5:pos":"copula","grammar:5821:ex4:points:0":"❗こないだの週末：last weekend.","grammar:5821:ex4:points:1":"こないだの週末：this past weekend.","grammar:5821:ex5:trans":"The trip the other day was fun.","grammar:5821:ex5:structure":"こないだの〜が楽しかった","grammar:5821:ex5:words:0:zh":"the other day","grammar:5821:ex5:words:0:note":"こないだ","grammar:5821:ex5:words:0:pos":"adverb","grammar:5821:ex5:words:1:zh":"'s","grammar:5821:ex5:words:1:pos":"particle","grammar:5821:ex5:words:2:zh":"travel / trip","grammar:5821:ex5:words:2:note":"りょこう","grammar:5821:ex5:words:2:pos":"noun","grammar:5821:ex5:words:3:zh":"(nominative)","grammar:5821:ex5:words:3:pos":"particle","grammar:5821:ex5:words:4:zh":"(past) was interesting","grammar:5821:ex5:words:4:note":"たのしかった","grammar:5821:ex5:words:4:pos":"adjective","grammar:5821:ex5:points:0":"❗こないだの旅行：the trip the other day.","grammar:5821:ex5:points:1":"こないだの旅行：last trip."},"5822":{"example:5822:exzh":"Time passes quickly.","example:5822:exzh2":"Once summer passes, it gets cool.","example:5822:exzh3":"The memories of him never fade away.","example:5822:exzh4":"Everything is destined to pass away.","example:5822:exzh5":"I recall the days that have passed."},"5823":{"example:5823:exzh":"This soup has a strong flavor.","example:5823:exzh2":"I like strong coffee.","example:5823:exzh3":"Her makeup is a little heavy.","example:5823:exzh4":"This color is very deep, isn't it?","example:5823:exzh5":"I like dishes with strong seasoning."},"5824":{"example:5824:exzh":"We need to cut the budget.","example:5824:exzh2":"We will make cuts for environmental protection.","example:5824:exzh3":"The impact of the cuts is big.","example:5824:exzh4":"Spending cuts are being called for.","example:5824:exzh5":"This plan includes cuts."},"5825":{"example:5825:exzh":"One martini, please.","example:5825:exzh2":"He likes drinking martinis.","example:5825:exzh3":"The martinis at this shop are delicious.","example:5825:exzh4":"A martini is a stylish cocktail.","example:5825:exzh5":"Let's talk over martinis."},"5826":{"example:5826:exzh":"When I asked about the wallet, my little brother played dumb and looked away.","example:5826:exzh2":"Please don't play dumb.","example:5826:exzh3":"She looks like she's playing dumb.","example:5826:exzh4":"I can't forgive that playing-dumb attitude."},"5827":{"example:5827:exzh":"Lately he travels often.","example:5827:exzh2":"This train runs frequently.","example:5827:exzh3":"She frequently talks with her friends on the phone.","example:5827:exzh4":"Exercising frequently is good for your health.","example:5827:exzh5":"This issue often becomes a topic of conversation."},"5828":{"example:5828:exzh":"I work hard at my job every day.","example:5828:exzh2":"He is working hard at his studies.","example:5828:exzh3":"We will work hard to achieve our goals.","example:5828:exzh4":"Work hard to get good results.","example:5828:exzh5":"It's important to work hard for your own growth."},"5829":{"example:5829:exzh":"She is a very intelligent student.","example:5829:exzh2":"A wise judgment is required.","example:5829:exzh3":"He is intelligent and good at solving problems.","example:5829:exzh4":"Intelligence is the key to success.","example:5829:exzh5":"She made a wise choice."},"5830":{"example:5830:exzh":"He is nine years old.","example:5830:exzh2":"There are nine apples.","example:5830:exzh3":"Let's meet at nine.","example:5830:exzh4":"I work in a team of nine.","example:5830:exzh5":"I succeeded on my ninth try.","grammar:5830:ex:trans":"He is nine years old.","grammar:5830:ex:structure":"〜は＋nounです. 「九歳」 = nine years old.","grammar:5830:ex:explain":"This is the 「Aは〜です」 statement pattern used for talking about age. 「九歳」 is a noun made of 「九」 plus the counter 「歳」, and it takes 「です」 directly for a polite statement. The topic 「彼」 takes 「は」. Note that Japanese counts age with 「〜歳」, and 「九歳」 is pronounced 「きゅうさい」; this is the most basic way to state an age.","grammar:5830:ex:words:0:zh":"he","grammar:5830:ex:words:0:note":"かれ","grammar:5830:ex:words:0:pos":"pronoun","grammar:5830:ex:words:1:zh":"(topic marker)","grammar:5830:ex:words:1:pos":"particle","grammar:5830:ex:words:2:zh":"nine years old","grammar:5830:ex:words:2:note":"きゅうさい","grammar:5830:ex:words:2:pos":"noun","grammar:5830:ex:words:3:zh":"(polite form)","grammar:5830:ex:words:3:pos":"copula","grammar:5830:ex:points:0":"九歳（きゅうさい）: nine years old","grammar:5830:ex:points:1":"〜歳: … years old","grammar:5830:ex2:trans":"There are nine apples.","grammar:5830:ex2:structure":"〔九つのりんご〕＋が＋あります. 「九つ」 = nine (native Japanese number).","grammar:5830:ex2:words:0:zh":"nine (of something)","grammar:5830:ex2:words:0:note":"ここのつ","grammar:5830:ex2:words:0:pos":"noun","grammar:5830:ex2:words:1:zh":"'s","grammar:5830:ex2:words:1:pos":"particle","grammar:5830:ex2:words:2:zh":"apple","grammar:5830:ex2:words:2:note":"Apple","grammar:5830:ex2:words:2:pos":"noun","grammar:5830:ex2:words:3:zh":"(nominative)","grammar:5830:ex2:words:3:pos":"particle","grammar:5830:ex2:words:4:zh":"there is / are","grammar:5830:ex2:words:4:note":"exists / there is","grammar:5830:ex2:words:4:pos":"verb","grammar:5830:ex2:points:0":"九つ（ここのつ）: nine (native Japanese numeral)","grammar:5830:ex2:points:1":"りんご: apple","grammar:5830:ex3:trans":"Let's meet at nine.","grammar:5830:ex3:structure":"timeに＋会いましょう. 「九時に」 = at nine.","grammar:5830:ex3:words:0:zh":"nine o'clock","grammar:5830:ex3:words:0:note":"くじ","grammar:5830:ex3:words:0:pos":"noun","grammar:5830:ex3:words:1:zh":"(point in time)","grammar:5830:ex3:words:1:pos":"particle","grammar:5830:ex3:words:2:zh":"let's meet","grammar:5830:ex3:words:2:note":"あいましょう; ましょう makes a suggestion","grammar:5830:ex3:words:2:pos":"verb","grammar:5830:ex3:points:0":"九時（くじ）: nine o'clock","grammar:5830:ex3:points:1":"〜に会う: to meet (the time takes に)","grammar:5830:ex4:trans":"I work on a nine-person team.","grammar:5830:ex4:structure":"〔九人のチーム〕＋で、働いています. 「九人」 = nine people.","grammar:5830:ex4:words:0:zh":"nine people","grammar:5830:ex4:words:0:note":"きゅうにん","grammar:5830:ex4:words:0:pos":"noun","grammar:5830:ex4:words:1:zh":"'s","grammar:5830:ex4:words:1:pos":"particle","grammar:5830:ex4:words:2:zh":"team","grammar:5830:ex4:words:2:note":"loanword","grammar:5830:ex4:words:2:pos":"noun","grammar:5830:ex4:words:3:zh":"(place of the action)","grammar:5830:ex4:words:3:pos":"particle","grammar:5830:ex4:words:4:zh":"work","grammar:5830:ex4:words:4:note":"〜ている expresses a state","grammar:5830:ex4:words:4:pos":"verb","grammar:5830:ex4:points:0":"九人（きゅうにん）: nine people","grammar:5830:ex4:points:1":"〜人: … people (counter for people)","grammar:5830:ex5:trans":"I succeeded on my ninth attempt.","grammar:5830:ex5:structure":"〔九回目の挑戦〕＋で、成功しました. 「〜回目」 = the …th time.","grammar:5830:ex5:words:0:zh":"the ninth time","grammar:5830:ex5:words:0:note":"きゅうかいめ","grammar:5830:ex5:words:0:pos":"noun","grammar:5830:ex5:words:1:zh":"'s","grammar:5830:ex5:words:1:pos":"particle","grammar:5830:ex5:words:2:zh":"challenge; try","grammar:5830:ex5:words:2:note":"ちょうせん","grammar:5830:ex5:words:2:pos":"noun","grammar:5830:ex5:words:3:zh":"(by means of)","grammar:5830:ex5:words:3:pos":"particle","grammar:5830:ex5:words:4:zh":"succeeded","grammar:5830:ex5:words:4:note":"せいこうしました","grammar:5830:ex5:words:4:pos":"verb","grammar:5830:ex5:points:0":"〜回目: the …th time (九回目 = the ninth time)","grammar:5830:ex5:points:1":"挑戦: challenge","exam:5830:zh":"Five plus four gives an answer of nine.","exam:5830:why":"Five plus four equals 「九」. 「八」 is the result of five plus three, one less."},"5831":{"example:5831:exzh":"He is still childish.","example:5831:exzh2":"Let's avoid childish behavior.","example:5831:exzh3":"That idea might be a little childish.","example:5831:exzh4":"I don't want to forget my childlike feelings.","example:5831:exzh5":"Once you become an adult, you become less childish."},"5832":{"example:5832:exzh":"Exercising your rights is important.","example:5832:exzh2":"He exercised that right.","example:5832:exzh3":"Will you exercise it, or give it up?","example:5832:exzh4":"Shareholders can exercise their voting rights at the general meeting.","example:5832:exzh5":"She is ready to exercise it."},"5833":{"example:5833:exzh":"I gathered the members for the meeting.","example:5833:exzh2":"Calling people together can take time.","example:5833:exzh3":"He was summoned right away.","example:5833:exzh4":"I strongly hope the team will be called together.","example:5833:exzh5":"After we were gathered, the discussion started right away."},"5836":{"example:5836:exzh":"I barely made it in time for the exam.","example:5836:exzh2":"Time is extremely tight.","example:5836:exzh3":"I set off just barely before it started raining.","example:5836:exzh4":"I'll keep working hard until the very last moment.","example:5836:exzh5":"He barely kept his promise."},"5837":{"example:5837:exzh":"The deadline for submitting the manuscript is next week.","example:5837:exzh2":"He is writing a manuscript.","example:5837:exzh3":"I like checking manuscripts.","example:5837:exzh4":"This manuscript is very interesting.","example:5837:exzh5":"It takes a lot of time to finish a manuscript."},"5838":{"example:5838:exzh":"A virus was detected.","example:5838:exzh2":"The system detected an abnormality.","example:5838:exzh3":"We will analyze the detected data.","example:5838:exzh4":"The scientists detected a new kind of radiation.","example:5838:exzh5":"The car detected an obstacle."},"5839":{"example:5839:exzh":"I'm doing training to improve my skills.","example:5839:exzh2":"I want to increase my income.","example:5839:exzh3":"I will work hard to improve myself.","example:5839:exzh4":"I'll do my best with the aim of improving.","example:5839:exzh5":"To improve, you need to take on challenges."},"5840":{"example:5840:exzh":"It's very warm today, isn't it?","example:5840:exzh2":"I like spending time in warm places.","example:5840:exzh3":"I went out on a warm spring day.","example:5840:exzh4":"My house is warm even in winter.","example:5840:exzh5":"These clothes are warm and very comfortable."},"5841":{"example:5841:exzh":"Today's public hearing is very important.","example:5841:exzh2":"Was there a presentation at the public hearing?","example:5841:exzh3":"I checked what was covered at the public hearing.","example:5841:exzh4":"I plan to take part in the city's public hearing.","example:5841:exzh5":"You are expected to state your opinion at the public hearing."},"5842":{"example:5842:exzh":"Please answer the question.","example:5842:exzh2":"I responded to my friend's request for advice.","example:5842:exzh3":"I couldn't answer right away.","example:5842:exzh4":"I found a way to answer correctly.","example:5842:exzh5":"Answering this question is difficult.","grammar:5842:ex:trans":"Please answer the question.","grammar:5842:ex:structure":"〜に答えてください","grammar:5842:ex:explain":"The thing you answer, 「答える」, takes 「に」, so 「質問に答える」 means to answer a question. This 「に」 is a spot where learners easily misuse 「を」, so remember that it is 「〜に答える」. 「〜てください」 is made of the te-form 「答えて」 plus 「ください」 and is a polite request asking someone to do something.","grammar:5842:ex:words:0:zh":"problem","grammar:5842:ex:words:0:note":"しつもん","grammar:5842:ex:words:0:pos":"noun","grammar:5842:ex:words:1:zh":"(object)","grammar:5842:ex:words:1:pos":"particle","grammar:5842:ex:words:2:zh":"to answer","grammar:5842:ex:words:2:note":"こたえて","grammar:5842:ex:words:2:pos":"verb","grammar:5842:ex:words:3:zh":"please","grammar:5842:ex:words:3:pos":"auxiliary verb","grammar:5842:ex:points:0":"❗〜に答える: to answer ... (the target takes に).","grammar:5842:ex:points:1":"質問に答える: to answer a question.","grammar:5842:ex2:trans":"I responded to my friend's consultation.","grammar:5842:ex2:structure":"〜に答えました","grammar:5842:ex2:words:0:zh":"friend","grammar:5842:ex2:words:0:note":"ともだち","grammar:5842:ex2:words:0:pos":"noun","grammar:5842:ex2:words:1:zh":"'s","grammar:5842:ex2:words:1:pos":"particle","grammar:5842:ex2:words:2:zh":"consultation","grammar:5842:ex2:words:2:note":"そうだん","grammar:5842:ex2:words:2:pos":"noun","grammar:5842:ex2:words:3:zh":"(object)","grammar:5842:ex2:words:3:pos":"particle","grammar:5842:ex2:words:4:zh":"answered","grammar:5842:ex2:words:4:note":"こたえました","grammar:5842:ex2:words:4:pos":"verb","grammar:5842:ex2:points:0":"相談に答える: to respond to a consultation.","grammar:5842:ex2:points:1":"友達の相談: a friend's consultation.","grammar:5842:ex3:trans":"I couldn't answer right away.","grammar:5842:ex3:structure":"すぐに〜られませんでした","grammar:5842:ex3:explain":"「すぐに」 means immediately, and 「答えられる」 is the potential form of 「答える」, meaning to be able to answer. Turning it into the polite negative past gives 「答えられませんでした」, meaning that I was not able to answer at the time. Broken down piece by piece, 「ませ」 is the form 「ます」 takes before a negative, 「ん」 marks the negative, and 「でした」 is made of 「でし」 and 「た」; when studying, it is easiest to memorize 「ませんでした」 as one polite negative past ending. The subject is omitted in the sentence, and following the given translation it is understood as I. The Japanese also clearly carries a past meaning.","grammar:5842:ex3:words:0:zh":"immediately","grammar:5842:ex3:words:0:pos":"adverb","grammar:5842:ex3:words:1:zh":"(pairs with 「すぐ」 to mean immediately)","grammar:5842:ex3:words:1:pos":"particle","grammar:5842:ex3:words:2:zh":"to answer","grammar:5842:ex3:words:2:note":"こたえ","grammar:5842:ex3:words:2:pos":"verb","grammar:5842:ex3:words:3:zh":"(potential: able to)","grammar:5842:ex3:words:3:pos":"auxiliary verb","grammar:5842:ex3:words:4:zh":"(polite tone)","grammar:5842:ex3:words:4:pos":"auxiliary verb","grammar:5842:ex3:words:5:zh":"(negative)","grammar:5842:ex3:words:5:pos":"auxiliary verb","grammar:5842:ex3:words:6:zh":"(forms the polite negative past)","grammar:5842:ex3:words:6:pos":"auxiliary verb","grammar:5842:ex3:words:7:zh":"(past)","grammar:5842:ex3:words:7:pos":"auxiliary verb","grammar:5842:ex3:points:0":"The ichidan verb 「答える」 drops 「る」 and takes 「られる」 to become the potential form 「答えられる」, meaning to be able to answer.","grammar:5842:ex3:points:1":"「〜ませんでした」 is the polite negative past, expressing that something was not done or could not be done at the time.","grammar:5842:ex3:points:2":"「すぐに」 means immediately and here modifies the time of answering.","grammar:5842:ex4:trans":"I found a way to answer correctly.","grammar:5842:ex4:structure":"［〜く答える］方法を見つけた","grammar:5842:ex4:explain":"「正しく」 comes from the i-adjective 「正しい」 and here means correctly, modifying 「答える」. The whole 「正しく答える」 modifies the noun 「方法」 that follows, and no 「の」 is needed in between. 「方法を」 marks the thing that was found, and 「見つけた」 is the past form of 「見つける」, showing that it has already been found. The subject of the sentence is omitted, and following the given translation it is understood as I.","grammar:5842:ex4:words:0:zh":"correctly","grammar:5842:ex4:words:0:note":"ただしく","grammar:5842:ex4:words:0:pos":"i-adjective","grammar:5842:ex4:words:1:zh":"answer","grammar:5842:ex4:words:1:note":"こたえる","grammar:5842:ex4:words:1:pos":"verb","grammar:5842:ex4:words:2:zh":"way, method","grammar:5842:ex4:words:2:note":"ほうほう","grammar:5842:ex4:words:2:pos":"noun","grammar:5842:ex4:words:3:zh":"(object)","grammar:5842:ex4:words:3:pos":"particle","grammar:5842:ex4:words:4:zh":"find","grammar:5842:ex4:words:4:note":"みつけ","grammar:5842:ex4:words:4:pos":"verb","grammar:5842:ex4:words:5:zh":"(past)","grammar:5842:ex4:words:5:pos":"auxiliary verb","grammar:5842:ex4:points:0":"With an i-adjective such as 「正しい」, change the final 「い」 to 「く」 and 「正しく」 can then modify a verb.","grammar:5842:ex4:points:1":"「正しく答える」 goes directly before the noun 「方法」 to mean a way of answering correctly.","grammar:5842:ex4:points:2":"「見つける」 is a transitive verb, so the thing found is marked with 「を」.","grammar:5842:ex5:trans":"Answering this question is really difficult.","grammar:5842:ex5:structure":"〜のは難しいです","grammar:5842:ex5:words:0:zh":"this","grammar:5842:ex5:words:0:pos":"pre-noun adjectival","grammar:5842:ex5:words:1:zh":"problem","grammar:5842:ex5:words:1:note":"もんだい","grammar:5842:ex5:words:1:pos":"noun","grammar:5842:ex5:words:2:zh":"(object)","grammar:5842:ex5:words:2:pos":"particle","grammar:5842:ex5:words:3:zh":"to answer","grammar:5842:ex5:words:3:note":"こたえる","grammar:5842:ex5:words:3:pos":"verb","grammar:5842:ex5:words:4:zh":"(nominalizer)","grammar:5842:ex5:words:4:pos":"particle","grammar:5842:ex5:words:5:zh":"(topic)","grammar:5842:ex5:words:5:pos":"particle","grammar:5842:ex5:words:6:zh":"difficult","grammar:5842:ex5:words:6:note":"むずかしい","grammar:5842:ex5:words:6:pos":"adjective","grammar:5842:ex5:words:7:zh":"(polite form)","grammar:5842:ex5:words:7:pos":"copula","grammar:5842:ex5:points:0":"問題に答える: to answer a question.","grammar:5842:ex5:points:1":"〜のは難しい: it is hard to…","exam:5842:zh":"When answering the teacher's question, please raise your hand before speaking.","exam:5842:why":"「質問に答える」 is the natural collocation for answering a question. 「聞く」 means to listen or to ask, so it can't express answering the teacher's question here."},"5844":{"example:5844:exzh":"We'll split this project into parts and move forward.","example:5844:exzh2":"I made a plan for dividing it up.","example:5844:exzh3":"I'll pay the cost in installments.","example:5844:exzh4":"This data needs to be split.","example:5844:exzh5":"After splitting it, further analysis is needed."},"5845":{"example:5845:exzh":"His clothes are gray.","example:5845:exzh2":"A gray sky stretches out.","example:5845:exzh3":"The walls of this room are gray.","example:5845:exzh4":"My favorite color is gray.","example:5845:exzh5":"There's a gray cat in the garden."},"5847":{"example:5847:exzh":"There are many casinos in Las Vegas."},"5848":{"example:5848:exzh":"He is playing by swinging a sword around."},"5849":{"example:5849:exzh":"Gloria is kind to her friends."},"5850":{"example:5850:exzh":"You need air conditioning in summer.","grammar:5850:ex:trans":"You need air conditioning in summer.","grammar:5850:ex:structure":"timeは、nounが＋必要です. 「夏は」 = in summer.","grammar:5850:ex:explain":"The pattern 「〜が必要です」 says that something is needed, and the thing needed, 「エアコン」, takes 「が」. The topic 「夏」 is introduced with 「は」, giving the sense of 'as for summer'. 「必要」 is a na-adjective and takes 「です」 directly at the end. The sentence means you need air conditioning in summer, with 「は…が」 showing the relationship between the topic and the thing needed.","grammar:5850:ex:words:0:zh":"summer","grammar:5850:ex:words:0:note":"なつ","grammar:5850:ex:words:0:pos":"noun","grammar:5850:ex:words:1:zh":"(topic marker)","grammar:5850:ex:words:1:pos":"particle","grammar:5850:ex:words:2:zh":"air conditioning","grammar:5850:ex:words:2:note":"loanword, air con","grammar:5850:ex:words:2:pos":"noun","grammar:5850:ex:words:3:zh":"(nominative)","grammar:5850:ex:words:3:pos":"particle","grammar:5850:ex:words:4:zh":"necessary","grammar:5850:ex:words:4:note":"ひつよう","grammar:5850:ex:words:4:pos":"na-adjective","grammar:5850:ex:words:5:zh":"(polite form)","grammar:5850:ex:words:5:pos":"copula","grammar:5850:ex:points:0":"〜が必要: to need…","grammar:5850:ex:points:1":"エアコン: air conditioner, air conditioning"},"5851":{"example:5851:exzh":"He has a strong accent."},"5853":{"example:5853:exzh":"He has hyper energy."},"5854":{"example:5854:exzh":"You need to send the product back."},"5855":{"example:5855:exzh":"I pour water into the glass.","grammar:5855:ex:trans":"Pour the water into the glass.","grammar:5855:ex:structure":"nounを＋nounに＋注ぎます. 「〜に注ぐ」 = to pour into…","grammar:5855:ex:explain":"「注ぐ」 is a transitive verb (to pour); the liquid being poured, 「水」, takes 「を」, and the container it is poured into, 「コップ」, takes 「に」, marking the endpoint — where the liquid finally ends up. Remember the direction: the thing that moves takes 「を」, and the destination takes 「に」. The ending 「注ぎます」 is the polite present form. The whole sentence means pouring water into a glass.","grammar:5855:ex:words:0:zh":"water","grammar:5855:ex:words:0:note":"みず","grammar:5855:ex:words:0:pos":"noun","grammar:5855:ex:words:1:zh":"(object marker)","grammar:5855:ex:words:1:pos":"particle","grammar:5855:ex:words:2:zh":"cup","grammar:5855:ex:words:2:note":"loanword, kop","grammar:5855:ex:words:2:pos":"noun","grammar:5855:ex:words:3:zh":"(the destination)","grammar:5855:ex:words:3:pos":"particle","grammar:5855:ex:words:4:zh":"pour in","grammar:5855:ex:words:4:note":"そそぎます","grammar:5855:ex:words:4:pos":"verb","grammar:5855:ex:points:0":"〜に注ぐ: to pour into…","grammar:5855:ex:points:1":"コップ: cup, glass","exam:5855:zh":"I wanted to drink water, so I poured some into a cup and drank from the rim.","exam:5855:why":"「コップ」 is a cup for holding a drink and drinking from it directly. 「皿」 is a plate, which doesn't fit the everyday use of pouring water and drinking from it here."},"5856":{"example:5856:exzh":"He is a combat sports champion."},"5857":{"example:5857:exzh":"To start with, let's begin with something simple."},"5858":{"example:5858:exzh":"I've traveled to Massachusetts."},"5859":{"example:5859:exzh":"The bereaved family is mourning the deceased."},"5860":{"example:5860:exzh":"He is playing the saxophone."},"5862":{"example:5862:exzh":"The weather is sunny today.","example:5862:exzh2":"She is a very cheerful person.","example:5862:exzh3":"Cheerful music was playing.","example:5862:exzh4":"I like a cheerful atmosphere.","example:5862:exzh5":"Let's go outside in this lovely weather."},"5863":{"example:5863:exzh":"I love curry.","example:5863:exzh2":"Making curry is easy.","example:5863:exzh3":"I had curry for lunch.","example:5863:exzh4":"The curry at this restaurant is delicious.","example:5863:exzh5":"I prefer spicy curry.","grammar:5863:ex:trans":"I love curry.","grammar:5863:ex:structure":"〜は＋noun＋が＋大好きです.","grammar:5863:ex:explain":"In the like/dislike pattern 「〜が好き／大好き」, the thing you like takes 「が」, not 「を」 — a common stumbling block for learners. 「大好き」 is a na-adjective and stronger than 「好き」 (to love), and it takes 「です」 at the end. The topic 「私」 takes 「は」, giving the standard 「私は〜が大好きです」 like/dislike sentence.","grammar:5863:ex:words:0:zh":"I","grammar:5863:ex:words:0:note":"わたし","grammar:5863:ex:words:0:pos":"pronoun","grammar:5863:ex:words:1:zh":"(topic marker)","grammar:5863:ex:words:1:pos":"particle","grammar:5863:ex:words:2:zh":"curry","grammar:5863:ex:words:2:note":"loanword, curry","grammar:5863:ex:words:2:pos":"noun","grammar:5863:ex:words:3:zh":"(object marker)","grammar:5863:ex:words:3:pos":"particle","grammar:5863:ex:words:4:zh":"Love","grammar:5863:ex:words:4:note":"だいすき","grammar:5863:ex:words:4:pos":"na-adjective","grammar:5863:ex:words:5:zh":"(polite form)","grammar:5863:ex:words:5:pos":"copula","grammar:5863:ex:points:0":"〜が大好きです: to love …","grammar:5863:ex:points:1":"カレー: curry","grammar:5863:ex2:trans":"Making curry is easy.","grammar:5863:ex2:structure":"〔カレーを作る＋の〕＋は＋簡単です. 「〜のは簡単」 = doing… is easy.","grammar:5863:ex2:words:0:zh":"curry","grammar:5863:ex2:words:0:note":"loanword","grammar:5863:ex2:words:0:pos":"noun","grammar:5863:ex2:words:1:zh":"(object marker)","grammar:5863:ex2:words:1:pos":"particle","grammar:5863:ex2:words:2:zh":"do","grammar:5863:ex2:words:2:note":"つくる; dictionary form","grammar:5863:ex2:words:2:pos":"verb","grammar:5863:ex2:words:3:zh":"(nominalizer)","grammar:5863:ex2:words:3:pos":"particle","grammar:5863:ex2:words:4:zh":"(topic marker)","grammar:5863:ex2:words:4:pos":"particle","grammar:5863:ex2:words:5:zh":"easy","grammar:5863:ex2:words:5:note":"かんたん","grammar:5863:ex2:words:5:pos":"na-adjective","grammar:5863:ex2:words:6:zh":"(polite form)","grammar:5863:ex2:words:6:pos":"copula","grammar:5863:ex2:points:0":"verb＋の＋は: doing … (the act itself)","grammar:5863:ex2:points:1":"簡単: simple","grammar:5863:ex3:trans":"I had curry for lunch.","grammar:5863:ex3:structure":"時間に＋名詞を＋食べました. 「昼ごはんに」 = at lunchtime.","grammar:5863:ex3:words:0:zh":"lunch","grammar:5863:ex3:words:0:note":"ひるごはん","grammar:5863:ex3:words:0:pos":"noun","grammar:5863:ex3:words:1:zh":"(point in time)","grammar:5863:ex3:words:1:pos":"particle","grammar:5863:ex3:words:2:zh":"curry","grammar:5863:ex3:words:2:note":"loanword","grammar:5863:ex3:words:2:pos":"noun","grammar:5863:ex3:words:3:zh":"(object marker)","grammar:5863:ex3:words:3:pos":"particle","grammar:5863:ex3:words:4:zh":"ate","grammar:5863:ex3:words:4:note":"たべました","grammar:5863:ex3:words:4:pos":"verb","grammar:5863:ex3:points:0":"〜に: at … (a point in time; 昼ごはんに = at lunch)","grammar:5863:ex3:points:1":"カレー: curry","grammar:5863:ex4:trans":"The curry at this restaurant is delicious.","grammar:5863:ex4:structure":"〔this restaurant's curry〕＋は＋i-adjective＋です.","grammar:5863:ex4:words:0:zh":"this","grammar:5863:ex4:words:0:pos":"pre-noun adjectival","grammar:5863:ex4:words:1:zh":"store","grammar:5863:ex4:words:1:note":"みせ","grammar:5863:ex4:words:1:pos":"noun","grammar:5863:ex4:words:2:zh":"'s","grammar:5863:ex4:words:2:pos":"particle","grammar:5863:ex4:words:3:zh":"curry","grammar:5863:ex4:words:3:note":"loanword","grammar:5863:ex4:words:3:pos":"noun","grammar:5863:ex4:words:4:zh":"(topic marker)","grammar:5863:ex4:words:4:pos":"particle","grammar:5863:ex4:words:5:zh":"tasty","grammar:5863:ex4:words:5:note":"おいしい","grammar:5863:ex4:words:5:pos":"adjective","grammar:5863:ex4:words:6:zh":"(polite form)","grammar:5863:ex4:words:6:pos":"copula","grammar:5863:ex4:points:0":"この店のカレー: this restaurant's curry","grammar:5863:ex4:points:1":"美味しい: tasty","grammar:5863:ex5:trans":"I like spicy curry.","grammar:5863:ex5:structure":"〔spicy curry〕＋が＋好みです. 「〜が好み」 = to like… (好み = preference).","grammar:5863:ex5:words:0:zh":"spicy","grammar:5863:ex5:words:0:note":"loanword, spicy","grammar:5863:ex5:words:0:pos":"na-adjective","grammar:5863:ex5:words:1:zh":"curry","grammar:5863:ex5:words:1:note":"loanword","grammar:5863:ex5:words:1:pos":"noun","grammar:5863:ex5:words:2:zh":"(object marker)","grammar:5863:ex5:words:2:pos":"particle","grammar:5863:ex5:words:3:zh":"to like","grammar:5863:ex5:words:3:note":"このみ","grammar:5863:ex5:words:3:pos":"noun","grammar:5863:ex5:words:4:zh":"(polite form)","grammar:5863:ex5:words:4:pos":"copula","grammar:5863:ex5:points:0":"スパイシーな: spicy (loanword na-adjective)","grammar:5863:ex5:points:1":"〜が好み: to one's taste, to like…","exam:5863:zh":"Today's lunch is curry—meat and vegetables simmered with curry powder and poured over rice.","exam:5863:why":"A dish of meat and vegetables simmered with curry powder and poured over rice is 「カレー」. 「うどん」 is udon noodles, which doesn't fit the description of rice as the base."},"5864":{"example:5864:exzh":"There are lots of pine trees here.","example:5864:exzh2":"The pine needles are green.","example:5864:exzh3":"I like the scent of pine.","example:5864:exzh4":"I took a walk in the pine forest.","example:5864:exzh5":"Pine trees stay green even in winter."},"5865":{"example:5865:exzh":"Growing vegetables is my hobby.","example:5865:exzh2":"Fruit cultivation is thriving in this region.","example:5865:exzh3":"Please tell me the cultivation method.","example:5865:exzh4":"Growing herbs is easy.","example:5865:exzh5":"Many farmers practice organic farming."},"5866":{"example:5866:exzh":"Let's just let things take their course.","example:5866:exzh2":"This turn of events was unexpected.","example:5866:exzh3":"I've decided to watch how things develop.","example:5866:exzh4":"The outcome will change depending on how things develop.","example:5866:exzh5":"I'm looking forward to seeing how things turn out."},"5867":{"example:5867:exzh":"This pot is very beautiful.","example:5867:exzh2":"I put the flowers in this vase.","example:5867:exzh3":"The pot is made of ceramic.","example:5867:exzh4":"I collect old pots.","example:5867:exzh5":"Please put water in the pot."},"5868":{"example:5868:exzh":"I bought a used car.","example:5868:exzh2":"Used books are cheap.","example:5868:exzh3":"I looked around a secondhand shop.","example:5868:exzh4":"This used furniture is still usable.","example:5868:exzh5":"I'm looking for a used instrument."},"5869":{"example:5869:exzh":"Syria's culture is very rich.","example:5869:exzh2":"I've been to Syria.","example:5869:exzh3":"Syria is located in the Middle East.","example:5869:exzh4":"I like Syrian food.","example:5869:exzh5":"The people of Syria are very kind."},"5870":{"example:5870:exzh":"This is my trump card.","example:5870:exzh2":"I played my trump card in the match.","example:5870:exzh3":"You can't win without a trump card.","example:5870:exzh4":"His trump card is strategy.","example:5870:exzh5":"Timing matters when you play your trump card."},"5871":{"example:5871:exzh":"He works as a fisherman.","example:5871:exzh2":"A fisherman's work is hard.","example:5871:exzh3":"The fisherman caught some fish.","example:5871:exzh4":"The fishermen go out to sea.","example:5871:exzh5":"There are many fishermen in this town."},"5872":{"example:5872:exzh":"He dug up a new treasure.","example:5872:exzh2":"Use this tool to dig out the soil.","example:5872:exzh3":"The information that was unearthed is extremely important.","example:5872:exzh4":"She dug up money that had been buried underground.","example:5872:exzh5":"The work of digging it out is not easy."},"5873":{"example:5873:exzh":"There's a big spider in the garden.","example:5873:exzh2":"A spider web is hanging on the tree.","example:5873:exzh3":"She hates spiders.","example:5873:exzh4":"Spiders catch insects.","example:5873:exzh5":"This spider is poisonous."},"5875":{"example:5875:exzh":"I sometimes go to see movies.","example:5875:exzh2":"He sometimes arrives late.","example:5875:exzh3":"I take a walk sometimes.","example:5875:exzh4":"She sometimes cooks.","example:5875:exzh5":"I sometimes talk on the phone with friends.","grammar:5875:ex:trans":"I sometimes go to see movies.","grammar:5875:ex:structure":"時々〜を見に行きます","grammar:5875:ex:explain":"「時々」 is a frequency adverb meaning sometimes or occasionally. 「見に行く」 is the purpose expression made by taking a verb's ます形, dropping ます, and adding に行く; 「見に行く」 means to go and see, and this 「に」 marks the purpose of the movement. The object 「映画」 takes 「を」. The topic 「私」 takes 「は」, and the sentence ends in the polite present tense, which together with 「時々」 describes an occasional habit.","grammar:5875:ex:words:0:zh":"I","grammar:5875:ex:words:0:note":"わたし","grammar:5875:ex:words:0:pos":"pronoun","grammar:5875:ex:words:1:zh":"(topic)","grammar:5875:ex:words:1:pos":"particle","grammar:5875:ex:words:2:zh":"sometimes","grammar:5875:ex:words:2:note":"ときどき","grammar:5875:ex:words:2:pos":"adverb","grammar:5875:ex:words:3:zh":"movie","grammar:5875:ex:words:3:note":"えいが","grammar:5875:ex:words:3:pos":"noun","grammar:5875:ex:words:4:zh":"(object marker)","grammar:5875:ex:words:4:pos":"particle","grammar:5875:ex:words:5:zh":"go to see","grammar:5875:ex:words:5:note":"みにいきます","grammar:5875:ex:words:5:pos":"verb","grammar:5875:ex:points:0":"❗時々（ときどき）：sometimes, occasionally (frequency adverb); 時々〜する = do … occasionally.","grammar:5875:ex:points:1":"時々：occasionally.","grammar:5875:ex2:trans":"He sometimes comes late.","grammar:5875:ex2:structure":"時々遅れて来る","grammar:5875:ex2:words:0:zh":"he","grammar:5875:ex2:words:0:note":"かれ","grammar:5875:ex2:words:0:pos":"pronoun","grammar:5875:ex2:words:1:zh":"(topic)","grammar:5875:ex2:words:1:pos":"particle","grammar:5875:ex2:words:2:zh":"sometimes","grammar:5875:ex2:words:2:note":"ときどき","grammar:5875:ex2:words:2:pos":"adverb","grammar:5875:ex2:words:3:zh":"late","grammar:5875:ex2:words:3:note":"おくれて","grammar:5875:ex2:words:3:pos":"verb","grammar:5875:ex2:words:4:zh":"come","grammar:5875:ex2:words:4:note":"くる","grammar:5875:ex2:words:4:pos":"verb","grammar:5875:ex2:points:0":"❗時々遅れて来る：sometimes comes late (遅れる = to be late).","grammar:5875:ex2:points:1":"時々遅れる：is sometimes late.","grammar:5875:ex3:trans":"I sometimes go for a walk.","grammar:5875:ex3:structure":"時々散歩をします","grammar:5875:ex3:words:0:zh":"occasionally","grammar:5875:ex3:words:0:note":"ときどき","grammar:5875:ex3:words:0:pos":"adverb","grammar:5875:ex3:words:1:zh":"take a walk","grammar:5875:ex3:words:1:note":"さんぽ","grammar:5875:ex3:words:1:pos":"noun","grammar:5875:ex3:words:2:zh":"(object marker)","grammar:5875:ex3:words:2:pos":"particle","grammar:5875:ex3:words:3:zh":"do","grammar:5875:ex3:words:3:pos":"verb","grammar:5875:ex3:points:0":"❗時々散歩をする：sometimes takes a walk.","grammar:5875:ex3:points:1":"時々散歩：a walk now and then.","grammar:5875:ex4:trans":"She occasionally cooks.","grammar:5875:ex4:structure":"時々料理をする","grammar:5875:ex4:words:0:zh":"she","grammar:5875:ex4:words:0:note":"かのじょ","grammar:5875:ex4:words:0:pos":"pronoun","grammar:5875:ex4:words:1:zh":"(topic)","grammar:5875:ex4:words:1:pos":"particle","grammar:5875:ex4:words:2:zh":"occasionally","grammar:5875:ex4:words:2:note":"ときどき","grammar:5875:ex4:words:2:pos":"adverb","grammar:5875:ex4:words:3:zh":"Cook","grammar:5875:ex4:words:3:note":"りょうり","grammar:5875:ex4:words:3:pos":"noun","grammar:5875:ex4:words:4:zh":"(object marker)","grammar:5875:ex4:words:4:pos":"particle","grammar:5875:ex4:words:5:zh":"do","grammar:5875:ex4:words:5:pos":"verb","grammar:5875:ex4:points:0":"❗時々料理をする：occasionally cooks.","grammar:5875:ex4:points:1":"時々料理：cooking now and then.","grammar:5875:ex5:trans":"I sometimes talk with friends on the phone.","grammar:5875:ex5:structure":"時々〜と電話します","grammar:5875:ex5:words:0:zh":"occasionally","grammar:5875:ex5:words:0:note":"ときどき","grammar:5875:ex5:words:0:pos":"adverb","grammar:5875:ex5:words:1:zh":"friend","grammar:5875:ex5:words:1:note":"ともだち","grammar:5875:ex5:words:1:pos":"noun","grammar:5875:ex5:words:2:zh":"(object)","grammar:5875:ex5:words:2:pos":"particle","grammar:5875:ex5:words:3:zh":"talk on the phone","grammar:5875:ex5:words:3:note":"でんわします","grammar:5875:ex5:words:3:pos":"verb","grammar:5875:ex5:points:0":"❗時々電話する：sometimes makes a phone call; 〜と = with …","grammar:5875:ex5:points:1":"時々電話：an occasional phone call.","exam:5875:zh":"Not every day, but about once a week, I sometimes eat lunch at this restaurant.","exam:5875:why":"「時々」 means sometimes, which fits the frequency of about once a week. 「いつも」 means always, which is different from the occasional frequency emphasized in the sentence."},"5876":{"example:5876:exzh":"His army marched along the border.","example:5876:exzh2":"We discussed the plan for the march.","example:5876:exzh3":"There have been many marches in history.","example:5876:exzh4":"Marching is part of war.","example:5876:exzh5":"A march requires a lot of strategy."},"5877":{"example:5877:exzh":"His physical strength has been declining with age.","example:5877:exzh2":"Her popularity is gradually fading.","example:5877:exzh3":"The body weakens with aging.","example:5877:exzh4":"Memory declines with age.","example:5877:exzh5":"Mental fatigue leads to decline."},"5879":{"example:5879:exzh":"Ras is a friend's name.","example:5879:exzh2":"She loves Ras.","example:5879:exzh3":"I'm planning to go out and have fun with Ras.","example:5879:exzh4":"Ras is an interesting person.","example:5879:exzh5":"Ras is my best friend."},"5880":{"example:5880:exzh":"I respect my family.","example:5880:exzh2":"You should respect his opinion.","example:5880:exzh3":"It's important to respect culture.","example:5880:exzh4":"We need values worth respecting.","example:5880:exzh5":"She shows respect with reverence."},"5881":{"example:5881:exzh":"Put a collar on the dog.","example:5881:exzh2":"The collar is too loose.","example:5881:exzh3":"I bought a collar for a cat.","example:5881:exzh4":"A name is written on the collar.","example:5881:exzh5":"His dog has a new collar."},"5882":{"example:5882:exzh":"You need to close the door.","example:5882:exzh2":"Please shut down the computer.","example:5882:exzh3":"Be careful when you close the book.","example:5882:exzh4":"Don't forget to close the window.","example:5882:exzh5":"When he finished reading the book, he closed it.","grammar:5882:ex:trans":"The door needs to be closed.","grammar:5882:ex:structure":"〜を閉じる必要があります","grammar:5882:ex:explain":"「閉じる」 is a transitive verb meaning to close or shut something such as a door, a book, or a lid, and the object 「ドア」 takes 「を」 (its opposite is 「開く」). The pattern 「〜必要があります」 means it is necessary to do something, and it follows the plain form of a verb, here 「閉じる」. The whole sentence means the door needs to be closed; it is a frame for stating necessity.","grammar:5882:ex:words:0:zh":"door","grammar:5882:ex:words:0:note":"loanword","grammar:5882:ex:words:0:pos":"noun","grammar:5882:ex:words:1:zh":"(object marker)","grammar:5882:ex:words:1:pos":"particle","grammar:5882:ex:words:2:zh":"to close","grammar:5882:ex:words:2:note":"とじる","grammar:5882:ex:words:2:pos":"verb","grammar:5882:ex:words:3:zh":"necessary","grammar:5882:ex:words:3:note":"ひつよう","grammar:5882:ex:words:3:pos":"noun","grammar:5882:ex:words:4:zh":"(nominative)","grammar:5882:ex:words:4:pos":"particle","grammar:5882:ex:words:5:zh":"there is / are","grammar:5882:ex:words:5:pos":"verb","grammar:5882:ex:points:0":"❗閉じる（とじる）：to close, to shut (a door, a book, a lid; transitive verb); vs 開く (to open).","grammar:5882:ex:points:1":"ドアを閉じる：close the door.","grammar:5882:ex2:trans":"Please close the computer.","grammar:5882:ex2:structure":"〜を閉じてください","grammar:5882:ex2:words:0:zh":"computer","grammar:5882:ex2:words:0:note":"loanword","grammar:5882:ex2:words:0:pos":"noun","grammar:5882:ex2:words:1:zh":"(object marker)","grammar:5882:ex2:words:1:pos":"particle","grammar:5882:ex2:words:2:zh":"to close","grammar:5882:ex2:words:2:note":"とじて","grammar:5882:ex2:words:2:pos":"verb","grammar:5882:ex2:words:3:zh":"please","grammar:5882:ex2:words:3:pos":"auxiliary verb","grammar:5882:ex2:points:0":"❗パソコンを閉じる：close the computer / shut the laptop; パソコン = computer.","grammar:5882:ex2:points:1":"パソコンを閉じる：close the computer.","grammar:5882:ex3:trans":"Be careful when you close a book.","grammar:5882:ex3:structure":"〜を閉じるときは気をつけて","grammar:5882:ex3:words:0:zh":"book","grammar:5882:ex3:words:0:note":"ほん","grammar:5882:ex3:words:0:pos":"noun","grammar:5882:ex3:words:1:zh":"(object marker)","grammar:5882:ex3:words:1:pos":"particle","grammar:5882:ex3:words:2:zh":"shut (a book)","grammar:5882:ex3:words:2:note":"とじる","grammar:5882:ex3:words:2:pos":"verb","grammar:5882:ex3:words:3:zh":"time","grammar:5882:ex3:words:3:pos":"noun","grammar:5882:ex3:words:4:zh":"(topic)","grammar:5882:ex3:words:4:pos":"particle","grammar:5882:ex3:words:5:zh":"be careful of","grammar:5882:ex3:words:5:note":"きをつけて","grammar:5882:ex3:words:5:pos":"verb","grammar:5882:ex3:points:0":"❗本を閉じる：shut a book; 〜ときは気をつけて = be careful when …","grammar:5882:ex3:points:1":"本を閉じる：close a book.","grammar:5882:ex4:trans":"Don't forget to close the window.","grammar:5882:ex4:structure":"〜を閉じるのを忘れないでください","grammar:5882:ex4:words:0:zh":"window","grammar:5882:ex4:words:0:note":"まど","grammar:5882:ex4:words:0:pos":"noun","grammar:5882:ex4:words:1:zh":"(object marker)","grammar:5882:ex4:words:1:pos":"particle","grammar:5882:ex4:words:2:zh":"turn off","grammar:5882:ex4:words:2:note":"とじる","grammar:5882:ex4:words:2:pos":"verb","grammar:5882:ex4:words:3:zh":"(nominalizer)","grammar:5882:ex4:words:3:pos":"particle","grammar:5882:ex4:words:4:zh":"(object marker)","grammar:5882:ex4:words:4:pos":"particle","grammar:5882:ex4:words:5:zh":"don't forget","grammar:5882:ex4:words:5:note":"わすれないで","grammar:5882:ex4:words:5:pos":"verb","grammar:5882:ex4:words:6:zh":"please","grammar:5882:ex4:words:6:pos":"auxiliary verb","grammar:5882:ex4:points:0":"❗窓を閉じる：close the window; 〜のを忘れないで = don't forget to …","grammar:5882:ex4:points:1":"窓を閉じる：close the window.","grammar:5882:ex5:trans":"After he finished reading the book, he closed it.","grammar:5882:ex5:structure":"〜たら閉じた","grammar:5882:ex5:words:0:zh":"he","grammar:5882:ex5:words:0:note":"かれ","grammar:5882:ex5:words:0:pos":"pronoun","grammar:5882:ex5:words:1:zh":"(topic)","grammar:5882:ex5:words:1:pos":"particle","grammar:5882:ex5:words:2:zh":"book","grammar:5882:ex5:words:2:note":"ほん","grammar:5882:ex5:words:2:pos":"noun","grammar:5882:ex5:words:3:zh":"(object marker)","grammar:5882:ex5:words:3:pos":"particle","grammar:5882:ex5:words:4:zh":"after finishing reading","grammar:5882:ex5:words:4:note":"よみおわったら","grammar:5882:ex5:words:4:pos":"verb","grammar:5882:ex5:words:5:zh":"closed it","grammar:5882:ex5:words:5:note":"とじた","grammar:5882:ex5:words:5:pos":"verb","grammar:5882:ex5:points:0":"❗読み終わる：to finish reading (読む + 終わる); 〜たら = after …","grammar:5882:ex5:points:1":"読み終わったら閉じる：close the book after finishing it."},"5883":{"example:5883:exzh":"Stanford University is famous.","example:5883:exzh2":"He studies at Stanford.","example:5883:exzh3":"There are many students at Stanford.","example:5883:exzh4":"She got into Stanford.","example:5883:exzh5":"The professors at Stanford are excellent."},"5884":{"example:5884:exzh":"The range of this gun is very long.","example:5884:exzh2":"It was designed with the range in mind.","example:5884:exzh3":"Measuring the range is difficult.","example:5884:exzh4":"His range is accurate.","example:5884:exzh5":"We developed new technology to extend the range."},"5886":{"example:5886:exzh":"Diana is a famous singer.","example:5886:exzh2":"Her name is Diana.","example:5886:exzh3":"I'm looking forward to meeting Diana.","example:5886:exzh4":"Diana gave a wonderful performance.","example:5886:exzh5":"I'm rooting for Diana."},"5887":{"example:5887:exzh":"I bought one liter of water.","example:5887:exzh2":"This bottle holds two liters.","example:5887:exzh3":"He made three liters of juice.","example:5887:exzh4":"A liter is a unit of volume.","example:5887:exzh5":"I bought one liter of milk.","grammar:5887:ex:trans":"I bought one liter of water.","grammar:5887:ex:structure":"水は 1リットル＋買いました","grammar:5887:ex:explain":"The key point here is that the counter 「1リットル」 sits directly before the verb and works as an adverb, with no particle needed, expressing 'bought one liter's worth.' 「買う」 is a transitive verb, and the topic 「水」 is marked with 「は」. In Japanese, counters very often attach bare to the front of the verb like this to express the amount involved in the action — a completely natural usage.","grammar:5887:ex:words:0:zh":"water","grammar:5887:ex:words:0:note":"みず","grammar:5887:ex:words:0:pos":"noun","grammar:5887:ex:words:1:zh":"(topic)","grammar:5887:ex:words:1:pos":"particle","grammar:5887:ex:words:2:zh":"one liter","grammar:5887:ex:words:2:note":"いちりっとる","grammar:5887:ex:words:2:pos":"noun","grammar:5887:ex:words:3:zh":"buy","grammar:5887:ex:words:3:note":"かいました","grammar:5887:ex:words:3:pos":"verb","grammar:5887:ex:points:0":"counter used adverbially: 1リットル (bought one liter)","grammar:5887:ex:points:1":"transitive verb 「買う」= to buy (水を買う)","grammar:5887:ex2:trans":"This bottle has a capacity of two liters.","grammar:5887:ex2:structure":"瓶は＋2リットルの容量です","grammar:5887:ex2:words:0:zh":"this","grammar:5887:ex2:words:0:pos":"pre-noun adjectival","grammar:5887:ex2:words:1:zh":"bottle","grammar:5887:ex2:words:1:note":"びん","grammar:5887:ex2:words:1:pos":"noun","grammar:5887:ex2:words:2:zh":"(topic)","grammar:5887:ex2:words:2:pos":"particle","grammar:5887:ex2:words:3:zh":"two liters","grammar:5887:ex2:words:3:note":"にりっとる","grammar:5887:ex2:words:3:pos":"noun","grammar:5887:ex2:words:4:zh":"'s","grammar:5887:ex2:words:4:pos":"particle","grammar:5887:ex2:words:5:zh":"capacity","grammar:5887:ex2:words:5:note":"ようりょう","grammar:5887:ex2:words:5:pos":"noun","grammar:5887:ex2:words:6:zh":"(assertion · polite)","grammar:5887:ex2:words:6:pos":"auxiliary verb","grammar:5887:ex2:points:0":"「〜の容量」= a capacity of 〜 (2リットルの容量)","grammar:5887:ex2:points:1":"AはBです: A is B (瓶は…容量)","grammar:5887:ex3:trans":"He made three liters of juice.","grammar:5887:ex3:structure":"ジュースを 3リットル＋作った","grammar:5887:ex3:words:0:zh":"he","grammar:5887:ex3:words:0:note":"かれ","grammar:5887:ex3:words:0:pos":"pronoun","grammar:5887:ex3:words:1:zh":"(topic)","grammar:5887:ex3:words:1:pos":"particle","grammar:5887:ex3:words:2:zh":"juice","grammar:5887:ex3:words:2:pos":"noun","grammar:5887:ex3:words:3:zh":"(object marker)","grammar:5887:ex3:words:3:pos":"particle","grammar:5887:ex3:words:4:zh":"three liters","grammar:5887:ex3:words:4:note":"さんりっとる","grammar:5887:ex3:words:4:pos":"noun","grammar:5887:ex3:words:5:zh":"to make, to prepare","grammar:5887:ex3:words:5:note":"つくった","grammar:5887:ex3:words:5:pos":"verb","grammar:5887:ex3:points:0":"counter used adverbially: 3リットル (made three liters)","grammar:5887:ex3:points:1":"transitive verb 「作る」= to make (ジュースを作る)","grammar:5887:ex4:trans":"A liter is a unit of capacity.","grammar:5887:ex4:structure":"リットルは＋容量の単位です","grammar:5887:ex4:words:0:zh":"liter","grammar:5887:ex4:words:0:pos":"noun","grammar:5887:ex4:words:1:zh":"(topic)","grammar:5887:ex4:words:1:pos":"particle","grammar:5887:ex4:words:2:zh":"capacity","grammar:5887:ex4:words:2:note":"ようりょう","grammar:5887:ex4:words:2:pos":"noun","grammar:5887:ex4:words:3:zh":"'s","grammar:5887:ex4:words:3:pos":"particle","grammar:5887:ex4:words:4:zh":"unit","grammar:5887:ex4:words:4:note":"たんい","grammar:5887:ex4:words:4:pos":"noun","grammar:5887:ex4:words:5:zh":"(assertion · polite)","grammar:5887:ex4:words:5:pos":"auxiliary verb","grammar:5887:ex4:points:0":"AはBです: A is B (リットルは…単位)","grammar:5887:ex4:points:1":"の linking nouns: 容量の単位 (a unit of capacity)","grammar:5887:ex5:trans":"I bought one liter of milk.","grammar:5887:ex5:structure":"1リットルの牛乳を＋買いました","grammar:5887:ex5:words:0:zh":"one liter","grammar:5887:ex5:words:0:note":"いちりっとる","grammar:5887:ex5:words:0:pos":"noun","grammar:5887:ex5:words:1:zh":"'s","grammar:5887:ex5:words:1:pos":"particle","grammar:5887:ex5:words:2:zh":"milk","grammar:5887:ex5:words:2:note":"ぎゅうにゅう","grammar:5887:ex5:words:2:pos":"noun","grammar:5887:ex5:words:3:zh":"(object marker)","grammar:5887:ex5:words:3:pos":"particle","grammar:5887:ex5:words:4:zh":"buy","grammar:5887:ex5:words:4:note":"かいました","grammar:5887:ex5:words:4:pos":"verb","grammar:5887:ex5:points:0":"「〜の＋noun」= 〜 of 〜 (1リットルの牛乳 = one liter of milk)","grammar:5887:ex5:points:1":"transitive verb 「買う」= to buy (牛乳を買う)"},"5888":{"example:5888:exzh":"That situation is awkward.","example:5888:exzh2":"I have an awkward relationship with him.","example:5888:exzh3":"An awkward silence followed.","example:5888:exzh4":"This topic is awkward.","example:5888:exzh5":"There was an awkward moment."},"5889":{"example:5889:exzh":"The park is over there.","example:5889:exzh2":"Do you know the house over there?","example:5889:exzh3":"Please look over there.","example:5889:exzh4":"He walked off over there.","example:5889:exzh5":"You can see the mountains over there.","grammar:5889:ex:trans":"The park is over there.","grammar:5889:ex:structure":"noun + は + noun + に + あります. 「向う」 = over there, the other side.","grammar:5889:ex:explain":"The existence pattern 「〜にある」 says that something is located somewhere, and the location 「向う」 (over there, the other side) is marked with 「に」. Because a park is inanimate, the sentence uses 「ある」 rather than 「いる」. The topic 「公園」 is introduced with 「は」. The ending 「あります」 is the polite form, and the whole sentence explains where the park is.","grammar:5889:ex:words:0:zh":"park","grammar:5889:ex:words:0:note":"こうえん","grammar:5889:ex:words:0:pos":"noun","grammar:5889:ex:words:1:zh":"(topic marker)","grammar:5889:ex:words:1:pos":"particle","grammar:5889:ex:words:2:zh":"over there","grammar:5889:ex:words:2:note":"むこう","grammar:5889:ex:words:2:pos":"noun","grammar:5889:ex:words:3:zh":"(the place where something exists)","grammar:5889:ex:words:3:pos":"particle","grammar:5889:ex:words:4:zh":"there is / to be","grammar:5889:ex:words:4:note":"exists / there is","grammar:5889:ex:words:4:pos":"verb","grammar:5889:ex:points:0":"向う（むこう）: over there, the other side","grammar:5889:ex:points:1":"〜にある: to be at … (location)","grammar:5889:ex2:trans":"Do you know the house over there?","grammar:5889:ex2:structure":"〔向うの家〕 + は + 知っていますか. 「向うの」 = the one over there.","grammar:5889:ex2:words:0:zh":"over there","grammar:5889:ex2:words:0:note":"むこう","grammar:5889:ex2:words:0:pos":"noun","grammar:5889:ex2:words:1:zh":"'s","grammar:5889:ex2:words:1:pos":"particle","grammar:5889:ex2:words:2:zh":"house","grammar:5889:ex2:words:2:note":"いえ","grammar:5889:ex2:words:2:pos":"noun","grammar:5889:ex2:words:3:zh":"(topic marker)","grammar:5889:ex2:words:3:pos":"particle","grammar:5889:ex2:words:4:zh":"know","grammar:5889:ex2:words:4:note":"〜ている expresses a state","grammar:5889:ex2:words:4:pos":"verb","grammar:5889:ex2:words:5:zh":"(question)","grammar:5889:ex2:words:5:pos":"particle","grammar:5889:ex2:points:0":"向うの + noun: the … over there","grammar:5889:ex2:points:1":"知っている: to know (a state)","grammar:5889:ex3:trans":"Please look over there.","grammar:5889:ex3:structure":"noun + を + 見てください. 「向うを見る」 = to look over there.","grammar:5889:ex3:words:0:zh":"over there","grammar:5889:ex3:words:0:note":"むこう","grammar:5889:ex3:words:0:pos":"noun","grammar:5889:ex3:words:1:zh":"(object marker)","grammar:5889:ex3:words:1:pos":"particle","grammar:5889:ex3:words:2:zh":"look","grammar:5889:ex3:words:2:note":"te-form","grammar:5889:ex3:words:2:pos":"verb","grammar:5889:ex3:words:3:zh":"please","grammar:5889:ex3:words:3:note":"〜てください","grammar:5889:ex3:words:3:pos":"verb","grammar:5889:ex3:points:0":"向うを見る: to look over there","grammar:5889:ex3:points:1":"〜てください: please do…","grammar:5889:ex4:trans":"He walked off in that direction.","grammar:5889:ex4:structure":"〜は + noun + に + 〔歩いて〕 + 行きました. 「歩いて行く」 = to walk off, to go on foot.","grammar:5889:ex4:words:0:zh":"he","grammar:5889:ex4:words:0:note":"かれ","grammar:5889:ex4:words:0:pos":"pronoun","grammar:5889:ex4:words:1:zh":"(topic marker)","grammar:5889:ex4:words:1:pos":"particle","grammar:5889:ex4:words:2:zh":"over there","grammar:5889:ex4:words:2:note":"むこう","grammar:5889:ex4:words:2:pos":"noun","grammar:5889:ex4:words:3:zh":"(direction)","grammar:5889:ex4:words:3:pos":"particle","grammar:5889:ex4:words:4:zh":"walk (and)","grammar:5889:ex4:words:4:note":"あるいて; te-form","grammar:5889:ex4:words:4:pos":"verb","grammar:5889:ex4:words:5:zh":"went","grammar:5889:ex4:words:5:note":"いきました","grammar:5889:ex4:words:5:pos":"verb","grammar:5889:ex4:points:0":"歩いて行く: to walk over there","grammar:5889:ex4:points:1":"向うに: toward that direction","grammar:5889:ex5:trans":"You can see the mountain over there.","grammar:5889:ex5:structure":"〔向うの山〕 + が + 見えます. 「見える」 = to be visible (naturally).","grammar:5889:ex5:words:0:zh":"over there","grammar:5889:ex5:words:0:note":"むこう","grammar:5889:ex5:words:0:pos":"noun","grammar:5889:ex5:words:1:zh":"'s","grammar:5889:ex5:words:1:pos":"particle","grammar:5889:ex5:words:2:zh":"mountain","grammar:5889:ex5:words:2:note":"やま","grammar:5889:ex5:words:2:pos":"noun","grammar:5889:ex5:words:3:zh":"(nominative)","grammar:5889:ex5:words:3:pos":"particle","grammar:5889:ex5:words:4:zh":"to be visible","grammar:5889:ex5:words:4:note":"みえます; spontaneous","grammar:5889:ex5:words:4:pos":"verb","grammar:5889:ex5:points:0":"見える: to be visible (naturally)","grammar:5889:ex5:points:1":"向うの山: the mountain over there"},"5890":{"example:5890:exzh":"He showed me his spoils.","example:5890:exzh2":"There was a gold medal among the spoils.","example:5890:exzh3":"I like collecting spoils.","example:5890:exzh4":"She was proud of her spoils.","example:5890:exzh5":"The spoils are his pride."},"5891":{"example:5891:exzh":"This line is thin.","example:5891:exzh2":"She has thin arms.","example:5891:exzh3":"I walk along a narrow path.","example:5891:exzh4":"I knit with thin yarn.","example:5891:exzh5":"His fingers are slender and long.","grammar:5891:ex:trans":"This line is thin.","grammar:5891:ex:structure":"〜は細いです","grammar:5891:ex:explain":"「細い」 is an i-adjective meaning thin or narrow (its opposites are 「太い」 thick and 「広い」 wide), and 「です」 is added directly at the end of the sentence. The topic 「線」 takes 「は」, and 「この」 is a pre-noun adjectival. The pattern 「〜は細いです」 is a basic sentence describing something as thin. Be careful not to mix up its direction with 「太い」.","grammar:5891:ex:words:0:zh":"this","grammar:5891:ex:words:0:pos":"pre-noun adjectival","grammar:5891:ex:words:1:zh":"line","grammar:5891:ex:words:1:note":"せん","grammar:5891:ex:words:1:pos":"noun","grammar:5891:ex:words:2:zh":"(topic)","grammar:5891:ex:words:2:pos":"particle","grammar:5891:ex:words:3:zh":"thin","grammar:5891:ex:words:3:note":"ほそい","grammar:5891:ex:words:3:pos":"adjective","grammar:5891:ex:words:4:zh":"(polite form)","grammar:5891:ex:words:4:pos":"copula","grammar:5891:ex:points:0":"❗細い（ほそい）：thin, narrow; vs 太い (thick) / 広い (wide).","grammar:5891:ex:points:1":"細い線：a thin line.","grammar:5891:ex2:trans":"She has thin arms.","grammar:5891:ex2:structure":"細い〜を持っています","grammar:5891:ex2:words:0:zh":"she","grammar:5891:ex2:words:0:note":"かのじょ","grammar:5891:ex2:words:0:pos":"pronoun","grammar:5891:ex2:words:1:zh":"(topic)","grammar:5891:ex2:words:1:pos":"particle","grammar:5891:ex2:words:2:zh":"thin","grammar:5891:ex2:words:2:note":"ほそい","grammar:5891:ex2:words:2:pos":"adjective","grammar:5891:ex2:words:3:zh":"arms","grammar:5891:ex2:words:3:note":"うで","grammar:5891:ex2:words:3:pos":"noun","grammar:5891:ex2:words:4:zh":"(object marker)","grammar:5891:ex2:words:4:pos":"particle","grammar:5891:ex2:words:5:zh":"there is / are","grammar:5891:ex2:words:5:note":"もっています","grammar:5891:ex2:words:5:pos":"verb","grammar:5891:ex2:points:0":"❗細い腕：slender arms; 腕 = arm.","grammar:5891:ex2:points:1":"細い腕：slender arms.","grammar:5891:ex3:trans":"I walk along a narrow road.","grammar:5891:ex3:structure":"細い〜を歩きます","grammar:5891:ex3:words:0:zh":"narrow, cramped","grammar:5891:ex3:words:0:note":"ほそい","grammar:5891:ex3:words:0:pos":"adjective","grammar:5891:ex3:words:1:zh":"road","grammar:5891:ex3:words:1:note":"みち","grammar:5891:ex3:words:1:pos":"noun","grammar:5891:ex3:words:2:zh":"(path)","grammar:5891:ex3:words:2:pos":"particle","grammar:5891:ex3:words:3:zh":"walk","grammar:5891:ex3:words:3:note":"あるきます","grammar:5891:ex3:words:3:pos":"verb","grammar:5891:ex3:points:0":"❗細い道：a narrow road (細い also describes narrow roads); 〜を歩く = to walk (along a road).","grammar:5891:ex3:points:1":"細い道：a narrow road.","grammar:5891:ex4:trans":"I knit with thin yarn.","grammar:5891:ex4:structure":"細い〜で編み物をします","grammar:5891:ex4:words:0:zh":"thin","grammar:5891:ex4:words:0:note":"ほそい","grammar:5891:ex4:words:0:pos":"adjective","grammar:5891:ex4:words:1:zh":"line","grammar:5891:ex4:words:1:note":"いと","grammar:5891:ex4:words:1:pos":"noun","grammar:5891:ex4:words:2:zh":"(means)","grammar:5891:ex4:words:2:pos":"particle","grammar:5891:ex4:words:3:zh":"knitting","grammar:5891:ex4:words:3:note":"あみもの","grammar:5891:ex4:words:3:pos":"noun","grammar:5891:ex4:words:4:zh":"(object marker)","grammar:5891:ex4:words:4:pos":"particle","grammar:5891:ex4:words:5:zh":"do","grammar:5891:ex4:words:5:pos":"verb","grammar:5891:ex4:points:0":"❗細い糸：thin yarn; 編み物 = knitting; 〜で = with … (means).","grammar:5891:ex4:points:1":"細い糸：thin yarn.","grammar:5891:ex5:trans":"His fingers are thin and long.","grammar:5891:ex5:structure":"AはBが〜くて〜です","grammar:5891:ex5:words:0:zh":"he","grammar:5891:ex5:words:0:note":"かれ","grammar:5891:ex5:words:0:pos":"pronoun","grammar:5891:ex5:words:1:zh":"(topic)","grammar:5891:ex5:words:1:pos":"particle","grammar:5891:ex5:words:2:zh":"fingers","grammar:5891:ex5:words:2:note":"ゆび","grammar:5891:ex5:words:2:pos":"noun","grammar:5891:ex5:words:3:zh":"(subject)","grammar:5891:ex5:words:3:pos":"particle","grammar:5891:ex5:words:4:zh":"thin","grammar:5891:ex5:words:4:note":"ほそくて; the te-form of 細い","grammar:5891:ex5:words:4:pos":"adjective","grammar:5891:ex5:words:5:zh":"long","grammar:5891:ex5:words:5:note":"ながい","grammar:5891:ex5:words:5:pos":"adjective","grammar:5891:ex5:words:6:zh":"(polite form)","grammar:5891:ex5:words:6:pos":"copula","grammar:5891:ex5:points:0":"「指が細い」: 「細い」 describes thinness in terms of how thick something is, and its opposite is 「太い」 (thick).","grammar:5891:ex5:points:1":"「細くて長い」: an i-adjective drops its い and adds 「くて」, which links two adjectives together and means thin and long.","exam:5891:zh":"These two lines are the same length but different in thickness: this one is the thick line, and that one is the thin line.","exam:5891:why":"「細い」 means thin, contrasting with 「太い」 in thickness. 「短い」 means short, but the sentence already says the two lines are the same length."},"5892":{"example:5892:exzh":"Copper is a good conductor.","example:5892:exzh2":"The electrical wiring in my house is made of copper.","example:5892:exzh3":"Copper forms a blue-green oxide.","example:5892:exzh4":"Many coins are made of copper.","example:5892:exzh5":"Copper has been used since ancient times."},"5893":{"example:5893:exzh":"I will act as you command.","example:5893:exzh2":"His command is important to us.","example:5893:exzh3":"We will go ahead with the preparations as commanded.","example:5893:exzh4":"I respect your command.","example:5893:exzh5":"I have confirmed the contents of the command."},"5894":{"example:5894:exzh":"He paid a fine for a traffic violation.","example:5894:exzh2":"Fines increase year after year.","example:5894:exzh3":"If you are late, you get a fine.","example:5894:exzh4":"Sometimes you have to pay a fine.","example:5894:exzh5":"Fines are set by law."},"5895":{"example:5895:exzh":"A treaty between nation and nation was concluded.","example:5895:exzh2":"We need to check the contents of the treaty.","example:5895:exzh3":"A new treaty has been concluded.","example:5895:exzh4":"International treaties are important.","example:5895:exzh5":"A treaty has legal force."},"5896":{"example:5896:exzh":"His background is very interesting.","example:5896:exzh2":"Some people hide their background.","example:5896:exzh3":"A background investigation was carried out.","example:5896:exzh4":"I want to know his background.","example:5896:exzh5":"The background has come to light."},"5897":{"example:5897:exzh":"The movement of the hands and feet is important.","example:5897:exzh2":"He dances with his arms and legs.","example:5897:exzh3":"My hands and feet got cold.","example:5897:exzh4":"When you exercise, your hands and feet get warm.","example:5897:exzh5":"Some people have limited use of their hands and feet."},"5898":{"example:5898:exzh":"He accepted that proposal.","example:5898:exzh2":"A signature is required to agree to the contract.","example:5898:exzh3":"Getting her consent was not easy.","example:5898:exzh4":"With consent, we can move on to the next step.","example:5898:exzh5":"Giving consent is an important responsibility."},"5899":{"example:5899:exzh":"Are you okay?","example:5899:exzh2":"I'm fine, so don't worry.","example:5899:exzh3":"That's fine.","example:5899:exzh4":"I believe you'll be fine.","example:5899:exzh5":"It's okay, it'll heal soon.","grammar:5899:ex:trans":"Are you okay?","grammar:5899:ex:structure":"大丈夫ですか？","grammar:5899:ex:explain":"「大丈夫」 is a na-adjective meaning all right, no problem, no harm done. Here it is the predicate at the end of the sentence and takes 「です」 directly, and then the question particle 「か」 turns it into the question 「大丈夫ですか」, meaning are you okay, are you all right? This is the most common thing to say when you are worried about someone, and the tone is natural and polite.","grammar:5899:ex:words:0:zh":"I'm fine","grammar:5899:ex:words:0:note":"だいじょうぶ","grammar:5899:ex:words:0:pos":"na-adjective","grammar:5899:ex:words:1:zh":"(polite form)","grammar:5899:ex:words:1:pos":"copula","grammar:5899:ex:words:2:zh":"(question)","grammar:5899:ex:words:2:pos":"particle","grammar:5899:ex:points:0":"❗大丈夫（だいじょうぶ）: all right, no problem (na-adjective).","grammar:5899:ex:points:1":"大丈夫ですか: are you okay?","grammar:5899:ex2:trans":"I'm fine, so don't worry.","grammar:5899:ex2:structure":"〜だから心配しないで","grammar:5899:ex2:words:0:zh":"I","grammar:5899:ex2:words:0:note":"わたし","grammar:5899:ex2:words:0:pos":"pronoun","grammar:5899:ex2:words:1:zh":"(topic)","grammar:5899:ex2:words:1:pos":"particle","grammar:5899:ex2:words:2:zh":"I'm fine","grammar:5899:ex2:words:2:note":"だいじょうぶ","grammar:5899:ex2:words:2:pos":"na-adjective","grammar:5899:ex2:words:3:zh":"is","grammar:5899:ex2:words:3:pos":"copula","grammar:5899:ex2:words:4:zh":"because","grammar:5899:ex2:words:4:pos":"particle","grammar:5899:ex2:words:5:zh":"don't worry","grammar:5899:ex2:words:5:note":"しんぱいしないで","grammar:5899:ex2:words:5:pos":"verb","grammar:5899:ex2:points:0":"〜だから: because…","grammar:5899:ex2:points:1":"心配しないで: don't worry.","grammar:5899:ex3:trans":"That's fine.","grammar:5899:ex3:structure":"〜は大丈夫だよ","grammar:5899:ex3:words:0:zh":"that","grammar:5899:ex3:words:0:pos":"pronoun","grammar:5899:ex3:words:1:zh":"(topic)","grammar:5899:ex3:words:1:pos":"particle","grammar:5899:ex3:words:2:zh":"it's fine","grammar:5899:ex3:words:2:note":"だいじょうぶ","grammar:5899:ex3:words:2:pos":"na-adjective","grammar:5899:ex3:words:3:zh":"is","grammar:5899:ex3:words:3:pos":"copula","grammar:5899:ex3:words:4:zh":"(reassuring)","grammar:5899:ex3:words:4:pos":"particle","grammar:5899:ex3:points:0":"大丈夫だよ: it's fine.","grammar:5899:ex3:points:1":"よ: nuance / tone (informing, reassuring)","grammar:5899:ex4:trans":"I believe you'll be fine.","grammar:5899:ex4:structure":"〜だと信じています","grammar:5899:ex4:words:0:zh":"you","grammar:5899:ex4:words:0:pos":"pronoun","grammar:5899:ex4:words:1:zh":"(topic)","grammar:5899:ex4:words:1:pos":"particle","grammar:5899:ex4:words:2:zh":"I'm fine","grammar:5899:ex4:words:2:note":"だいじょうぶ","grammar:5899:ex4:words:2:pos":"na-adjective","grammar:5899:ex4:words:3:zh":"is","grammar:5899:ex4:words:3:pos":"copula","grammar:5899:ex4:words:4:zh":"(quotation)","grammar:5899:ex4:words:4:pos":"particle","grammar:5899:ex4:words:5:zh":"believe in","grammar:5899:ex4:words:5:note":"しんじています","grammar:5899:ex4:words:5:pos":"verb","grammar:5899:ex4:points:0":"❗〜だと信じる: to believe that… (quotation)","grammar:5899:ex4:points:1":"大丈夫だと信じる: to believe that things will be fine.","grammar:5899:ex5:trans":"It's okay, it'll heal soon.","grammar:5899:ex5:structure":"大丈夫、すぐに治ります","grammar:5899:ex5:words:0:zh":"it's okay","grammar:5899:ex5:words:0:note":"だいじょうぶ","grammar:5899:ex5:words:0:pos":"na-adjective","grammar:5899:ex5:words:1:zh":"right away","grammar:5899:ex5:words:1:pos":"adverb","grammar:5899:ex5:words:2:zh":"heal","grammar:5899:ex5:words:2:note":"なおります","grammar:5899:ex5:words:2:pos":"verb","grammar:5899:ex5:points:0":"❗治る: to heal (intransitive verb).","grammar:5899:ex5:points:1":"すぐに治る: to heal quickly.","exam:5899:zh":"I fell, but I'm not hurt and can walk on my own, so I'm fine.","exam:5899:why":"「大丈夫」 means there's no problem, that you're fine. 「痛い」 means painful, which doesn't fit the meaning here of saying you're okay."}};